import { cn } from "@hunt/styled-ui";
import React, { useEffect, useMemo, useState } from "react";
import activityLogCsvUrl from "../../assets/stats/activity_log.csv";
import hintLogCsvUrl from "../../assets/stats/hint_log.csv";
import puzzlesTasksCsvUrl from "../../assets/stats/puzzles_tasks.csv";
import teamInfoCsvUrl from "../../assets/stats/team_info.csv";
import { loadCsvText, parseCsv, parseCsvToObjects } from "./csv";

type TeamInfoRow = {
  team_id: string;
  username: string;
  team_name: string;
};

type PuzzleRow = {
  puzzle_slug: string;
  title: string;
  is_task: string;
  round_slug: string;
  is_meta: string;
  is_supermeta: string;
  is_runaround: string;
};

type TeamInfo = {
  id: string;
  name: string;
};

type PuzzleInfo = {
  slug: string;
  title: string;
};

type AnswerStatus = "correct" | "partial" | "incorrect";
type TeamSortColumn =
  | "teamName"
  | "totalGuesses"
  | "unlockTime"
  | "solveTime"
  | "timeToSolve";
type AnswerSortColumn = "answer" | "count";

type LoadState =
  | { status: "loading" }
  | { status: "error"; message: string }
  | { status: "ready"; data: PuzzleStatsData };

type PuzzleStatsData = {
  puzzleTitle: string;
  teamsUnlocked: number;
  teamsSolved: number;
  totalGuesses: number;
  totalHints: number;
  teamRows: TeamRow[];
  answerRows: AnswerRow[];
};

type TeamRow = {
  teamId: string;
  teamName: string;
  totalGuesses: number;
  unlockTimeMs: number | null;
  solveTimeMs: number | null;
  timeToSolveMs: number | null;
};

type AnswerRow = {
  answer: string;
  count: number;
  status: AnswerStatus;
};

const buildTeamInfo = (rows: TeamInfoRow[]): TeamInfo[] => {
  return rows.map((row) => ({
    id: row.team_id,
    name: row.team_name || row.username,
  }));
};

const buildPuzzleInfo = (rows: PuzzleRow[]): PuzzleInfo[] => {
  return rows.map((row) => ({
    slug: row.puzzle_slug,
    title: row.title,
  }));
};

const parseTimestamp = (value: string): number | null => {
  const trimmed = value.trim();
  if (!trimmed) return null;
  const match =
    /^(\d{4}-\d{2}-\d{2}) (\d{2}:\d{2}:\d{2})(?:\.(\d+))?([+-]\d{2})(?::?(\d{2}))?$/.exec(
      trimmed,
    );
  if (!match) return null;
  const date = match[1];
  const time = match[2];
  const fraction = match[3] ?? "0";
  const tzHour = match[4];
  const tzMinute = match[5] ?? "00";
  const ms = fraction.padEnd(3, "0").slice(0, 3);
  const iso = `${date}T${time}.${ms}${tzHour}:${tzMinute}`;
  const parsed = Date.parse(iso);
  return Number.isFinite(parsed) ? parsed : null;
};

const formatTimestampWithEt = (timestampMs: number) => {
  const date = new Date(timestampMs);
  const formatter = new Intl.DateTimeFormat("en-US", {
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hour12: false,
    timeZone: "America/New_York",
  });
  const parts = formatter.formatToParts(date);
  const get = (type: string) =>
    parts.find((part) => part.type === type)?.value ?? "";
  const year = get("year");
  const month = get("month");
  const day = get("day");
  const hour = get("hour");
  const minute = get("minute");
  const second = get("second");
  const fraction = `${Math.floor((timestampMs % 1000) / 10)}`.padStart(2, "0");
  return `${year}-${month}-${day} ${hour}:${minute}:${second}.${fraction} ET`;
};

const formatDuration = (durationMs: number) => {
  if (durationMs < 60000) {
    return `${(Math.max(0, durationMs) / 1000).toFixed(2)}s`;
  }
  const totalSeconds = Math.max(0, Math.round(durationMs / 1000));
  if (totalSeconds < 3600) {
    const minutes = Math.floor(totalSeconds / 60);
    const seconds = totalSeconds % 60;
    return `${minutes}m ${seconds}s`;
  }
  const hours = Math.floor(totalSeconds / 3600);
  const minutes = Math.floor((totalSeconds % 3600) / 60);
  const seconds = totalSeconds % 60;
  return `${hours}h ${minutes}m ${seconds}s`;
};

const safeParseJson = (value: string) => {
  if (!value) return null;
  try {
    return JSON.parse(value) as Record<string, unknown>;
  } catch {
    return null;
  }
};

const normalizeAnswerStatus = (status: string | undefined): AnswerStatus => {
  if (status === "correct") return "correct";
  if (status === "incorrect") return "incorrect";
  return "partial";
};

const statusPriority: Record<AnswerStatus, number> = {
  incorrect: 0,
  partial: 1,
  correct: 2,
};

const SECTION_CLASS =
  "space-y-4 rounded-2xl border border-white/10 bg-[#2d1a44] p-6 shadow-[0_18px_40px_rgba(17,8,35,0.35)]";

const CARD_CLASS =
  "rounded-xl border border-white/10 bg-gradient-to-br from-white/10 to-white/5 px-4 py-3 shadow-[inset_0_1px_0_rgba(255,255,255,0.15)]";
const TEAM_STATS_LINK_CLASS =
  "text-white underline decoration-white/30 underline-offset-2 hover:decoration-white/80";
const PUZZLE_LINK_CLASS =
  "text-white underline decoration-white/30 underline-offset-2 hover:decoration-white/80";
const getAriaSort = (isActive: boolean, direction: "asc" | "desc") =>
  isActive ? (direction === "asc" ? "ascending" : "descending") : "none";

const PuzzleStatsPage = ({ slug }: { slug: string }) => {
  const [state, setState] = useState<LoadState>({ status: "loading" });
  const [teamFilter, setTeamFilter] = useState("");
  const [teamSort, setTeamSort] = useState<{
    column: TeamSortColumn;
    direction: "asc" | "desc";
  }>({ column: "solveTime", direction: "asc" });
  const [teamPage, setTeamPage] = useState(1);
  const [answerSort, setAnswerSort] = useState<{
    column: AnswerSortColumn;
    direction: "asc" | "desc";
  }>({ column: "count", direction: "desc" });
  const [answerPage, setAnswerPage] = useState(1);

  useEffect(() => {
    let cancelled = false;
    const load = async () => {
      try {
        const [teamText, puzzleText, activityText, hintText] =
          await Promise.all([
            loadCsvText(teamInfoCsvUrl),
            loadCsvText(puzzlesTasksCsvUrl),
            loadCsvText(activityLogCsvUrl),
            loadCsvText(hintLogCsvUrl),
          ]);

        if (cancelled) return;

        const teamInfoRows = parseCsvToObjects<TeamInfoRow>(teamText);
        const puzzleRows = parseCsvToObjects<PuzzleRow>(puzzleText);
        const teams = buildTeamInfo(teamInfoRows);
        const puzzles = buildPuzzleInfo(puzzleRows);
        const teamById = new Map(teams.map((team) => [team.id, team]));
        const puzzleBySlug = new Map(
          puzzles.map((puzzle) => [puzzle.slug, puzzle]),
        );

        const unlockByTeam = new Map<string, number>();
        const solveByTeam = new Map<string, number>();
        const guessCountsByTeam = new Map<string, number>();
        const answerStats = new Map<
          string,
          { count: number; status: AnswerStatus }
        >();
        let totalGuesses = 0;

        let header: string[] = [];
        let idxTimestamp = -1;
        let idxTeamId = -1;
        let idxType = -1;
        let idxSlug = -1;
        let idxData = -1;

        parseCsv(activityText, (row, rowIndex) => {
          if (rowIndex === 0) {
            header = row;
            idxTimestamp = header.indexOf("timestamp");
            idxTeamId = header.indexOf("team_id");
            idxType = header.indexOf("type");
            idxSlug = header.indexOf("slug");
            idxData = header.indexOf("data");
            const missing = [
              ["timestamp", idxTimestamp],
              ["team_id", idxTeamId],
              ["type", idxType],
              ["slug", idxSlug],
              ["data", idxData],
            ]
              .filter(([, idx]) => idx === -1)
              .map(([name]) => name as string);
            if (missing.length > 0) {
              throw new Error(
                `Missing required columns in activity_log.csv: ${missing.join(", ")}`,
              );
            }
            return;
          }

          const entrySlug = row[idxSlug] ?? "";
          if (entrySlug !== slug) return;

          const type = row[idxType] ?? "";
          const teamId = row[idxTeamId] ?? "";
          const timestamp = row[idxTimestamp] ?? "";
          const timeMs = parseTimestamp(timestamp);

          if (!teamId) return;

          if (type === "puzzle_unlocked" && timeMs !== null) {
            const existing = unlockByTeam.get(teamId);
            if (!existing || timeMs < existing) {
              unlockByTeam.set(teamId, timeMs);
            }
          }

          if (type === "puzzle_solved" && timeMs !== null) {
            const existing = solveByTeam.get(teamId);
            if (!existing || timeMs < existing) {
              solveByTeam.set(teamId, timeMs);
            }
          }

          if (type === "puzzle_guess_submitted") {
            totalGuesses += 1;
            guessCountsByTeam.set(
              teamId,
              (guessCountsByTeam.get(teamId) ?? 0) + 1,
            );
            const data = safeParseJson(row[idxData] ?? "");
            const canonical =
              typeof data?.canonical_input === "string"
                ? data.canonical_input
                : typeof data?.input === "string"
                  ? data.input
                  : typeof data?.guess === "string"
                    ? data.guess
                    : null;
            if (canonical) {
              const statusValue =
                typeof data?.status === "string" ? data.status : undefined;
              const status = normalizeAnswerStatus(statusValue);
              const existing = answerStats.get(canonical);
              if (existing) {
                existing.count += 1;
                if (statusPriority[status] > statusPriority[existing.status]) {
                  existing.status = status;
                }
              } else {
                answerStats.set(canonical, { count: 1, status });
              }
            }
          }
        });

        let totalHints = 0;
        let hintHeader: string[] = [];
        let hintTypeIdx = -1;
        let hintSlugIdx = -1;
        let hintTimestampIdx = -1;
        parseCsv(hintText, (row, rowIndex) => {
          if (rowIndex === 0) {
            hintHeader = row;
            hintTypeIdx = hintHeader.indexOf("type");
            hintSlugIdx = hintHeader.indexOf("slug");
            hintTimestampIdx = hintHeader.indexOf("timestamp");
            const missing = [
              ["timestamp", hintTimestampIdx],
              ["type", hintTypeIdx],
              ["slug", hintSlugIdx],
            ]
              .filter(([, idx]) => idx === -1)
              .map(([name]) => name as string);
            if (missing.length > 0) {
              throw new Error(
                `Missing required columns in hint_log.csv: ${missing.join(", ")}`,
              );
            }
            return;
          }
          const entrySlug = row[hintSlugIdx] ?? "";
          if (entrySlug !== slug) return;
          const type = row[hintTypeIdx] ?? "";
          if (type === "hint_requested") {
            totalHints += 1;
          }
        });

        const teamIds = new Set<string>([
          ...unlockByTeam.keys(),
          ...solveByTeam.keys(),
          ...guessCountsByTeam.keys(),
        ]);

        const teamRows: TeamRow[] = Array.from(teamIds).map((teamId) => {
          const unlockTimeMs = unlockByTeam.get(teamId) ?? null;
          const solveTimeMs = solveByTeam.get(teamId) ?? null;
          const timeToSolveMs =
            unlockTimeMs !== null && solveTimeMs !== null
              ? solveTimeMs - unlockTimeMs
              : null;
          return {
            teamId,
            teamName: teamById.get(teamId)?.name ?? `Team ${teamId}`,
            totalGuesses: guessCountsByTeam.get(teamId) ?? 0,
            unlockTimeMs,
            solveTimeMs,
            timeToSolveMs,
          };
        });

        teamRows.sort((a, b) => {
          if (a.solveTimeMs !== null && b.solveTimeMs !== null) {
            return a.solveTimeMs - b.solveTimeMs;
          }
          if (a.solveTimeMs !== null) return -1;
          if (b.solveTimeMs !== null) return 1;
          if (a.unlockTimeMs !== null && b.unlockTimeMs !== null) {
            return a.unlockTimeMs - b.unlockTimeMs;
          }
          if (a.unlockTimeMs !== null) return -1;
          if (b.unlockTimeMs !== null) return 1;
          return a.teamName.localeCompare(b.teamName);
        });

        const answerRows = Array.from(answerStats.entries())
          .map(([answer, info]) => ({
            answer,
            count: info.count,
            status: info.status,
          }))
          .sort((a, b) => {
            if (a.count !== b.count) return b.count - a.count;
            return a.answer.localeCompare(b.answer);
          });

        const puzzleTitle = puzzleBySlug.get(slug)?.title ?? slug;

        const data: PuzzleStatsData = {
          puzzleTitle,
          teamsUnlocked: unlockByTeam.size,
          teamsSolved: solveByTeam.size,
          totalGuesses,
          totalHints,
          teamRows,
          answerRows,
        };

        if (!cancelled) {
          setState({ status: "ready", data });
        }
      } catch (error) {
        if (!cancelled) {
          setState({
            status: "error",
            message:
              error instanceof Error
                ? error.message
                : "Failed to load puzzle stats",
          });
        }
      }
    };

    void load();

    return () => {
      cancelled = true;
    };
  }, [slug]);

  const data = state.status === "ready" ? state.data : null;

  const filteredTeamRows = useMemo(() => {
    if (!data) return [] as TeamRow[];
    const needle = teamFilter.trim().toLowerCase();
    const rows = needle
      ? data.teamRows.filter((row) =>
          row.teamName.toLowerCase().includes(needle),
        )
      : data.teamRows;

    const compareNullableNumber = (
      a: number | null,
      b: number | null,
      direction: "asc" | "desc",
    ) => {
      if (a === null && b === null) return 0;
      if (a === null) return 1;
      if (b === null) return -1;
      return direction === "asc" ? a - b : b - a;
    };

    const compareStrings = (
      a: string,
      b: string,
      direction: "asc" | "desc",
    ) => {
      const result = a.localeCompare(b);
      return direction === "asc" ? result : -result;
    };

    return [...rows].sort((a, b) => {
      switch (teamSort.column) {
        case "teamName":
          return compareStrings(a.teamName, b.teamName, teamSort.direction);
        case "totalGuesses":
          return teamSort.direction === "asc"
            ? a.totalGuesses - b.totalGuesses
            : b.totalGuesses - a.totalGuesses;
        case "unlockTime":
          return compareNullableNumber(
            a.unlockTimeMs,
            b.unlockTimeMs,
            teamSort.direction,
          );
        case "solveTime":
          return compareNullableNumber(
            a.solveTimeMs,
            b.solveTimeMs,
            teamSort.direction,
          );
        case "timeToSolve":
          return compareNullableNumber(
            a.timeToSolveMs,
            b.timeToSolveMs,
            teamSort.direction,
          );
        default:
          return 0;
      }
    });
  }, [data, teamFilter, teamSort.column, teamSort.direction]);

  const teamPageSize = 50;
  const teamTotalPages = Math.max(
    1,
    Math.ceil(filteredTeamRows.length / teamPageSize),
  );
  const teamSafePage = Math.min(teamPage, teamTotalPages);
  const teamStartIndex = (teamSafePage - 1) * teamPageSize;
  const teamEndIndex = teamStartIndex + teamPageSize;
  const visibleTeamRows = filteredTeamRows.slice(teamStartIndex, teamEndIndex);

  useEffect(() => {
    setTeamPage(1);
  }, [teamFilter, teamSort.column, teamSort.direction, data?.teamRows.length]);

  const sortedAnswerRows = useMemo(() => {
    if (!data) return [] as AnswerRow[];
    const rows = [...data.answerRows];
    rows.sort((a, b) => {
      if (answerSort.column === "count") {
        if (a.count !== b.count) {
          return answerSort.direction === "asc"
            ? a.count - b.count
            : b.count - a.count;
        }
        const labelCompare = a.answer.localeCompare(b.answer);
        return answerSort.direction === "asc" ? labelCompare : -labelCompare;
      }
      const labelCompare = a.answer.localeCompare(b.answer);
      return answerSort.direction === "asc" ? labelCompare : -labelCompare;
    });
    return rows;
  }, [data, answerSort.column, answerSort.direction]);

  const answerPageSize = 50;
  const answerTotalPages = Math.max(
    1,
    Math.ceil(sortedAnswerRows.length / answerPageSize),
  );
  const answerSafePage = Math.min(answerPage, answerTotalPages);
  const answerStartIndex = (answerSafePage - 1) * answerPageSize;
  const answerEndIndex = answerStartIndex + answerPageSize;
  const visibleAnswerRows = sortedAnswerRows.slice(
    answerStartIndex,
    answerEndIndex,
  );

  useEffect(() => {
    setAnswerPage(1);
  }, [answerSort.column, answerSort.direction, data?.answerRows.length]);

  const answerEmoji = (status: AnswerStatus) => {
    if (status === "correct") return "\u2705";
    if (status === "incorrect") return "\u274C\uFE0F";
    return "\u2755\uFE0F";
  };

  if (state.status === "loading") {
    return (
      <div className={cn(SECTION_CLASS, "text-center text-sm text-white/80")}>
        Loading puzzle stats…
      </div>
    );
  }

  if (state.status === "error") {
    return (
      <div className="rounded-2xl border border-red-300/60 bg-red-500/15 p-6 text-center text-sm text-white/90 shadow-[0_18px_40px_rgba(17,8,35,0.35)]">
        {state.message}
      </div>
    );
  }

  if (!data) {
    return null;
  }

  return (
    <div className="space-y-6">
      <a
        href="/wrapup"
        className="inline-flex items-center text-xs uppercase tracking-wide text-white/70 underline decoration-white/30 underline-offset-2 hover:text-white hover:decoration-white/80"
      >
        ← Back to Wrap-up
      </a>
      <h2 className="text-2xl font-title text-white sm:text-3xl">
        Puzzle Statistics for{" "}
        <a href={`/puzzles/${slug}`} className={PUZZLE_LINK_CLASS}>
          {data.puzzleTitle}
        </a>
      </h2>

      <section className={SECTION_CLASS}>
        <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-4">
          <div className={CARD_CLASS}>
            <div className="text-xs uppercase tracking-wide text-white/60">
              Teams unlocked
            </div>
            <div className="text-2xl font-semibold text-white">
              {data.teamsUnlocked.toLocaleString()}
            </div>
          </div>
          <div className={CARD_CLASS}>
            <div className="text-xs uppercase tracking-wide text-white/60">
              Teams solved
            </div>
            <div className="text-2xl font-semibold text-white">
              {data.teamsSolved.toLocaleString()}
            </div>
          </div>
          <div className={CARD_CLASS}>
            <div className="text-xs uppercase tracking-wide text-white/60">
              Guesses submitted
            </div>
            <div className="text-2xl font-semibold text-white">
              {data.totalGuesses.toLocaleString()}
            </div>
          </div>
          <div className={CARD_CLASS}>
            <div className="text-xs uppercase tracking-wide text-white/60">
              Hints requested
            </div>
            <div className="text-2xl font-semibold text-white">
              {data.totalHints.toLocaleString()}
            </div>
          </div>
        </div>
      </section>

      <section className={SECTION_CLASS}>
        <div className="flex flex-wrap items-center justify-between gap-3">
          <div className="space-y-1">
            <h3 className="text-lg font-semibold text-white">Team Activity</h3>
            <span className="text-xs text-white/60">Times shown in ET.</span>
          </div>
          <div className="flex flex-wrap items-center gap-2 text-xs text-white/70">
            <input
              type="text"
              value={teamFilter}
              onChange={(event) => {
                setTeamFilter(event.target.value);
              }}
              placeholder="Search team"
              className="min-w-[160px] rounded-md border border-white/20 bg-white/10 px-2 py-1 text-xs text-white placeholder:text-white/40 focus:outline-none focus:ring-2 focus:ring-white/40"
            />
            <div>
              Showing{" "}
              {filteredTeamRows.length === 0
                ? "0"
                : `${(teamStartIndex + 1).toLocaleString()}-${Math.min(
                    teamEndIndex,
                    filteredTeamRows.length,
                  ).toLocaleString()}`}{" "}
              of {filteredTeamRows.length.toLocaleString()} entries
            </div>
            <div className="flex items-center gap-2">
              <button
                type="button"
                className="rounded-md border border-white/20 bg-white/5 px-2 py-1 text-xs hover:bg-white/15 disabled:opacity-40"
                onClick={() => {
                  setTeamPage((current) => Math.max(1, current - 1));
                }}
                disabled={teamSafePage <= 1}
              >
                Prev
              </button>
              <span>
                Page {teamSafePage} of {teamTotalPages}
              </span>
              <button
                type="button"
                className="rounded-md border border-white/20 bg-white/5 px-2 py-1 text-xs hover:bg-white/15 disabled:opacity-40"
                onClick={() => {
                  setTeamPage((current) =>
                    Math.min(teamTotalPages, current + 1),
                  );
                }}
                disabled={teamSafePage >= teamTotalPages}
              >
                Next
              </button>
            </div>
          </div>
        </div>
        <div className="overflow-x-auto rounded-xl border border-white/10 bg-white/5">
          <table className="min-w-full text-sm">
            <thead className="bg-white/10 text-xs uppercase tracking-wide text-white/70">
              <tr>
                <th
                  className="px-3 py-2 text-left"
                  aria-sort={getAriaSort(
                    teamSort.column === "teamName",
                    teamSort.direction,
                  )}
                >
                  <button
                    type="button"
                    onClick={() => {
                      setTeamSort((current) => ({
                        column: "teamName",
                        direction:
                          current.column === "teamName" &&
                          current.direction === "asc"
                            ? "desc"
                            : "asc",
                      }));
                    }}
                    className="inline-flex items-center gap-1 text-left text-xs font-semibold uppercase tracking-wide text-white/80 hover:text-white"
                  >
                    Team
                    {teamSort.column === "teamName" && (
                      <span className="text-[10px]">
                        {teamSort.direction === "asc" ? "↑" : "↓"}
                      </span>
                    )}
                  </button>
                </th>
                <th
                  className="px-3 py-2 text-right"
                  aria-sort={getAriaSort(
                    teamSort.column === "totalGuesses",
                    teamSort.direction,
                  )}
                >
                  <button
                    type="button"
                    onClick={() => {
                      setTeamSort((current) => ({
                        column: "totalGuesses",
                        direction:
                          current.column === "totalGuesses" &&
                          current.direction === "asc"
                            ? "desc"
                            : "asc",
                      }));
                    }}
                    className="inline-flex items-center gap-1 text-right text-xs font-semibold uppercase tracking-wide text-white/80 hover:text-white"
                  >
                    Total guesses
                    {teamSort.column === "totalGuesses" && (
                      <span className="text-[10px]">
                        {teamSort.direction === "asc" ? "↑" : "↓"}
                      </span>
                    )}
                  </button>
                </th>
                <th
                  className="px-3 py-2 text-left"
                  aria-sort={getAriaSort(
                    teamSort.column === "unlockTime",
                    teamSort.direction,
                  )}
                >
                  <button
                    type="button"
                    onClick={() => {
                      setTeamSort((current) => ({
                        column: "unlockTime",
                        direction:
                          current.column === "unlockTime" &&
                          current.direction === "asc"
                            ? "desc"
                            : "asc",
                      }));
                    }}
                    className="inline-flex items-center gap-1 text-left text-xs font-semibold uppercase tracking-wide text-white/80 hover:text-white"
                  >
                    Unlock time
                    {teamSort.column === "unlockTime" && (
                      <span className="text-[10px]">
                        {teamSort.direction === "asc" ? "↑" : "↓"}
                      </span>
                    )}
                  </button>
                </th>
                <th
                  className="px-3 py-2 text-left"
                  aria-sort={getAriaSort(
                    teamSort.column === "solveTime",
                    teamSort.direction,
                  )}
                >
                  <button
                    type="button"
                    onClick={() => {
                      setTeamSort((current) => ({
                        column: "solveTime",
                        direction:
                          current.column === "solveTime" &&
                          current.direction === "asc"
                            ? "desc"
                            : "asc",
                      }));
                    }}
                    className="inline-flex items-center gap-1 text-left text-xs font-semibold uppercase tracking-wide text-white/80 hover:text-white"
                  >
                    Solve time
                    {teamSort.column === "solveTime" && (
                      <span className="text-[10px]">
                        {teamSort.direction === "asc" ? "↑" : "↓"}
                      </span>
                    )}
                  </button>
                </th>
                <th
                  className="px-3 py-2 text-left"
                  aria-sort={getAriaSort(
                    teamSort.column === "timeToSolve",
                    teamSort.direction,
                  )}
                >
                  <button
                    type="button"
                    onClick={() => {
                      setTeamSort((current) => ({
                        column: "timeToSolve",
                        direction:
                          current.column === "timeToSolve" &&
                          current.direction === "asc"
                            ? "desc"
                            : "asc",
                      }));
                    }}
                    className="inline-flex items-center gap-1 text-left text-xs font-semibold uppercase tracking-wide text-white/80 hover:text-white"
                  >
                    Time to solve
                    {teamSort.column === "timeToSolve" && (
                      <span className="text-[10px]">
                        {teamSort.direction === "asc" ? "↑" : "↓"}
                      </span>
                    )}
                  </button>
                </th>
              </tr>
            </thead>
            <tbody>
              {visibleTeamRows.map((row) => (
                <tr
                  key={row.teamId}
                  className="border-t border-white/10 odd:bg-white/5"
                >
                  <td className="px-3 py-2">
                    <a
                      href={`/stats/${row.teamId}`}
                      className={TEAM_STATS_LINK_CLASS}
                    >
                      {row.teamName}
                    </a>
                  </td>
                  <td className="px-3 py-2 text-right tabular-nums">
                    {row.totalGuesses.toLocaleString()}
                  </td>
                  <td className="px-3 py-2 text-xs text-white/70">
                    {row.unlockTimeMs !== null
                      ? formatTimestampWithEt(row.unlockTimeMs)
                      : "—"}
                  </td>
                  <td className="px-3 py-2 text-xs text-white/70">
                    {row.solveTimeMs !== null
                      ? formatTimestampWithEt(row.solveTimeMs)
                      : "—"}
                  </td>
                  <td className="px-3 py-2 text-xs text-white/70">
                    {row.timeToSolveMs !== null
                      ? formatDuration(row.timeToSolveMs)
                      : "—"}
                  </td>
                </tr>
              ))}
              {visibleTeamRows.length === 0 && (
                <tr>
                  <td
                    colSpan={5}
                    className="px-3 py-3 text-center text-sm text-white/70"
                  >
                    No team activity recorded yet.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </section>

      <section className={SECTION_CLASS}>
        <div className="flex flex-wrap items-center justify-between gap-3">
          <div className="space-y-1">
            <h3 className="text-lg font-semibold text-white">Answer Stats</h3>
            <span className="text-xs text-white/60">
              Sorted by submissions.
            </span>
          </div>
          <div className="flex flex-wrap items-center gap-2 text-xs text-white/70">
            <div>
              Showing{" "}
              {sortedAnswerRows.length === 0
                ? "0"
                : `${(answerStartIndex + 1).toLocaleString()}-${Math.min(
                    answerEndIndex,
                    sortedAnswerRows.length,
                  ).toLocaleString()}`}{" "}
              of {sortedAnswerRows.length.toLocaleString()} entries
            </div>
            <div className="flex items-center gap-2">
              <button
                type="button"
                className="rounded-md border border-white/20 bg-white/5 px-2 py-1 text-xs hover:bg-white/15 disabled:opacity-40"
                onClick={() => {
                  setAnswerPage((current) => Math.max(1, current - 1));
                }}
                disabled={answerSafePage <= 1}
              >
                Prev
              </button>
              <span>
                Page {answerSafePage} of {answerTotalPages}
              </span>
              <button
                type="button"
                className="rounded-md border border-white/20 bg-white/5 px-2 py-1 text-xs hover:bg-white/15 disabled:opacity-40"
                onClick={() => {
                  setAnswerPage((current) =>
                    Math.min(answerTotalPages, current + 1),
                  );
                }}
                disabled={answerSafePage >= answerTotalPages}
              >
                Next
              </button>
            </div>
          </div>
        </div>
        <div className="overflow-x-auto rounded-xl border border-white/10 bg-white/5">
          <table className="min-w-full text-sm">
            <thead className="bg-white/10 text-xs uppercase tracking-wide text-white/70">
              <tr>
                <th
                  className="px-3 py-2 text-left"
                  aria-sort={getAriaSort(
                    answerSort.column === "answer",
                    answerSort.direction,
                  )}
                >
                  <button
                    type="button"
                    onClick={() => {
                      setAnswerSort((current) => ({
                        column: "answer",
                        direction:
                          current.column === "answer" &&
                          current.direction === "asc"
                            ? "desc"
                            : "asc",
                      }));
                    }}
                    className="inline-flex items-center gap-1 text-left text-xs font-semibold uppercase tracking-wide text-white/80 hover:text-white"
                  >
                    Answer
                    {answerSort.column === "answer" && (
                      <span className="text-[10px]">
                        {answerSort.direction === "asc" ? "↑" : "↓"}
                      </span>
                    )}
                  </button>
                </th>
                <th
                  className="px-3 py-2 text-right"
                  aria-sort={getAriaSort(
                    answerSort.column === "count",
                    answerSort.direction,
                  )}
                >
                  <button
                    type="button"
                    onClick={() => {
                      setAnswerSort((current) => ({
                        column: "count",
                        direction:
                          current.column === "count" &&
                          current.direction === "asc"
                            ? "desc"
                            : "asc",
                      }));
                    }}
                    className="inline-flex items-center gap-1 text-right text-xs font-semibold uppercase tracking-wide text-white/80 hover:text-white"
                  >
                    Submissions
                    {answerSort.column === "count" && (
                      <span className="text-[10px]">
                        {answerSort.direction === "asc" ? "↑" : "↓"}
                      </span>
                    )}
                  </button>
                </th>
              </tr>
            </thead>
            <tbody>
              {visibleAnswerRows.map((row) => (
                <tr
                  key={`${row.status}-${row.answer}`}
                  className="border-t border-white/10 odd:bg-white/5"
                >
                  <td className="px-3 py-2 whitespace-normal break-words">
                    {answerEmoji(row.status)} {row.answer}
                  </td>
                  <td className="px-3 py-2 text-right tabular-nums">
                    {row.count.toLocaleString()}
                  </td>
                </tr>
              ))}
              {visibleAnswerRows.length === 0 && (
                <tr>
                  <td
                    colSpan={2}
                    className="px-3 py-3 text-center text-sm text-white/70"
                  >
                    No guesses recorded yet.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </section>
    </div>
  );
};

export default PuzzleStatsPage;
