import {
  Chart as ChartJS,
  BarController,
  BarElement,
  BubbleController,
  LineElement,
  LinearScale,
  PointElement,
  CategoryScale,
  ScatterController,
  type ChartDataset,
  type ChartOptions,
  type Plugin,
  type TooltipItem,
  Tooltip,
  Legend,
} from "chart.js";
import React, { useMemo } from "react";
import { Bar, Bubble, Line, Scatter } from "react-chartjs-2";

ChartJS.register(
  BarController,
  BarElement,
  BubbleController,
  LineElement,
  PointElement,
  ScatterController,
  CategoryScale,
  LinearScale,
  Tooltip,
  Legend,
);

export type SeriesPoint = { x: number; y: number };

export type Series = {
  id: string;
  label: string;
  color: string;
  points: SeriesPoint[];
};

export type ScatterPoint = {
  x: number;
  y: number;
  label: string;
  teamId: string;
};

export type BubblePoint = {
  x: number;
  y: number;
  r: number;
  label: string;
  teamId: string;
  teamSize: number;
  guesses: number;
  solves: number;
  color?: string;
};

export type TimelinePoint = {
  x: number;
  y: string;
  teamId: string;
  teamLabel: string;
  metaLabel: string;
};

export type TimelineSeries = {
  id: string;
  label: string;
  color: string;
  points: TimelinePoint[];
};

export type BarSeries = {
  id: string;
  label: string;
  color: string;
  data: number[];
};

type LineChartProps = {
  series: Series[];
  height?: number;
  formatAxisTime: (timestampMs: number) => string;
  formatTooltipTime: (timestampMs: number) => string;
  emptyMessage?: string;
  xTickSpacingMs?: number;
};

type ScatterChartProps = {
  points: ScatterPoint[];
  height?: number;
  emptyMessage?: string;
  xLabel: string;
  yLabel: string;
  pointColors?: string[];
};

type BubbleChartProps = {
  points: BubblePoint[];
  height?: number;
  emptyMessage?: string;
  xLabel: string;
  yLabel: string;
  pointColors?: string[];
};

type TimelineChartProps = {
  series: TimelineSeries[];
  teamLabels: string[];
  height?: number;
  emptyMessage?: string;
  formatAxisTime: (timestampMs: number) => string;
  formatTooltipTime: (timestampMs: number) => string;
  rangeStartMs?: number;
  rangeEndMs?: number;
};

type BarChartProps = {
  labels: string[];
  series: BarSeries[];
  height?: number;
  emptyMessage?: string;
  xLabel?: string;
  yLabel?: string;
  stacked?: boolean;
  showLegend?: boolean;
  xTickRotation?: number;
  barThickness?: number;
  categoryPercentage?: number;
  barPercentage?: number;
};

const DEFAULT_HEIGHT = 320;
const DEFAULT_X_TICK_SPACING_MS = 6 * 60 * 60 * 1000;
const TIMELINE_LEGEND_BOTTOM_PADDING_PX = 16;

const timelineLegendBottomPaddingPlugin: Plugin<"scatter"> = {
  id: "timelineLegendBottomPadding",
  afterUpdate: (chart) => {
    const legend = chart.legend as
      | (typeof chart.legend & {
          _timelineBottomPaddingApplied?: boolean;
        })
      | undefined;
    if (!legend || legend._timelineBottomPaddingApplied) {
      return;
    }

    const fit = legend.fit.bind(legend);
    legend.fit = () => {
      fit();
      legend.height += TIMELINE_LEGEND_BOTTOM_PADDING_PX;
    };
    legend._timelineBottomPaddingApplied = true;
  },
};

const toRgba = (color: string, alpha: number) => {
  const hex = color.trim();
  if (hex.startsWith("#")) {
    const normalized = hex.slice(1);
    if (normalized.length === 3) {
      const r = parseInt(normalized[0] + normalized[0], 16);
      const g = parseInt(normalized[1] + normalized[1], 16);
      const b = parseInt(normalized[2] + normalized[2], 16);
      return `rgba(${r},${g},${b},${alpha})`;
    }
    if (normalized.length === 6) {
      const r = parseInt(normalized.slice(0, 2), 16);
      const g = parseInt(normalized.slice(2, 4), 16);
      const b = parseInt(normalized.slice(4, 6), 16);
      return `rgba(${r},${g},${b},${alpha})`;
    }
  }
  const rgbMatch =
    /rgb\\s*\\(\\s*(\\d+)\\s*,\\s*(\\d+)\\s*,\\s*(\\d+)\\s*\\)/i.exec(color);
  if (rgbMatch) {
    const [, r, g, b] = rgbMatch;
    return `rgba(${r},${g},${b},${alpha})`;
  }
  const rgbaMatch =
    /rgba\\s*\\(\\s*(\\d+)\\s*,\\s*(\\d+)\\s*,\\s*(\\d+)\\s*,\\s*([\\d.]+)\\s*\\)/i.exec(
      color,
    );
  if (rgbaMatch) {
    const [, r, g, b] = rgbaMatch;
    return `rgba(${r},${g},${b},${alpha})`;
  }
  return color;
};

export const LineChart = ({
  series,
  height = DEFAULT_HEIGHT,
  formatAxisTime,
  formatTooltipTime,
  emptyMessage = "Select at least one team to see the chart.",
  xTickSpacingMs = DEFAULT_X_TICK_SPACING_MS,
}: LineChartProps) => {
  const allPoints = useMemo(
    () => series.flatMap((line) => line.points),
    [series],
  );
  const hasPoints = allPoints.length > 0;
  const minX = hasPoints ? Math.min(...allPoints.map((point) => point.x)) : 0;
  const maxX = hasPoints ? Math.max(...allPoints.map((point) => point.x)) : 0;
  const maxY = Math.max(1, ...allPoints.map((point) => point.y));

  const datasets = useMemo<ChartDataset<"line", SeriesPoint[]>[]>(
    () =>
      series.map((line) => {
        return {
          label: line.label,
          data: line.points,
          borderColor: line.color,
          backgroundColor: line.color,
          borderWidth: 2,
          pointRadius: 0,
          pointHoverRadius: 4,
          pointHitRadius: 12,
          tension: 0,
          fill: false,
          parsing: false as const,
          spanGaps: true,
        };
      }),
    [series],
  );

  const options = useMemo<ChartOptions<"line">>(
    () => ({
      responsive: true,
      maintainAspectRatio: false,
      animation: false,
      interaction: {
        mode: "nearest" as const,
        intersect: true,
      },
      plugins: {
        legend: { display: false },
        tooltip: {
          mode: "nearest",
          intersect: true,
          backgroundColor: "#231437",
          borderColor: "rgba(255,255,255,0.2)",
          borderWidth: 1,
          padding: 10,
          displayColors: false,
          callbacks: {
            title: (items: TooltipItem<"line">[]) => {
              const time = items[0]?.parsed.x;
              return typeof time === "number" ? formatTooltipTime(time) : "";
            },
            label: (item: TooltipItem<"line">) => {
              const value =
                typeof item.parsed.y === "number" ? item.parsed.y : 0;
              return `${item.dataset.label ?? "Team"}: ${value.toLocaleString()}`;
            },
          },
        },
      },
      scales: {
        x: {
          type: "linear" as const,
          min: hasPoints ? minX : undefined,
          max: hasPoints ? maxX : undefined,
          ticks: {
            stepSize: xTickSpacingMs,
            color: "rgba(255,255,255,0.7)",
            font: { size: 10 },
            autoSkip: false,
            maxRotation: 0,
            callback: (value: string | number) => formatAxisTime(Number(value)),
          },
          grid: {
            color: "rgba(255,255,255,0.1)",
          },
        },
        y: {
          beginAtZero: true,
          suggestedMax: hasPoints ? maxY : undefined,
          ticks: {
            color: "rgba(255,255,255,0.7)",
            font: { size: 10 },
          },
          grid: {
            color: "rgba(255,255,255,0.15)",
          },
        },
      },
    }),
    [
      formatAxisTime,
      formatTooltipTime,
      hasPoints,
      maxX,
      maxY,
      minX,
      xTickSpacingMs,
    ],
  );

  if (series.length === 0) {
    return (
      <div className="rounded-xl border border-white/10 bg-white/5 p-4 text-sm text-white/70">
        {emptyMessage}
      </div>
    );
  }

  return (
    <div className="rounded-xl border border-white/10 bg-white/5 p-4">
      <div style={{ height }}>
        <Line data={{ datasets }} options={options} aria-label="Line chart" />
      </div>
      <div className="mt-3 flex flex-wrap gap-3 text-xs text-white/70">
        {series.map((line) => (
          <div key={line.id} className="flex items-center gap-1">
            <span
              className="inline-block h-2 w-2 rounded-full"
              style={{ backgroundColor: line.color }}
            />
            <span>{line.label}</span>
          </div>
        ))}
      </div>
    </div>
  );
};

export const BarChart = ({
  labels,
  series,
  height = DEFAULT_HEIGHT,
  emptyMessage = "No data available.",
  xLabel,
  yLabel,
  stacked = false,
  showLegend = true,
  xTickRotation = 0,
  barThickness,
  categoryPercentage = 0.8,
  barPercentage = 0.8,
}: BarChartProps) => {
  const hasData = series.some((item) => item.data.some((value) => value > 0));
  const datasets = useMemo<ChartDataset<"bar", number[]>[]>(
    () =>
      series.map((item) => ({
        label: item.label,
        data: item.data,
        backgroundColor: item.color,
        borderColor: item.color,
        borderWidth: 0,
        barThickness,
        categoryPercentage,
        barPercentage,
      })),
    [barPercentage, barThickness, categoryPercentage, series],
  );

  const options = useMemo<ChartOptions<"bar">>(
    () => ({
      responsive: true,
      maintainAspectRatio: false,
      animation: false,
      interaction: {
        mode: "index" as const,
        intersect: false,
      },
      plugins: {
        legend: {
          display: showLegend,
          labels: {
            color: "rgba(255,255,255,0.7)",
            font: { size: 11 },
          },
        },
        tooltip: {
          mode: "index",
          intersect: false,
          backgroundColor: "#231437",
          borderColor: "rgba(255,255,255,0.2)",
          borderWidth: 1,
          padding: 10,
          callbacks: {
            title: (items: TooltipItem<"bar">[]) => items[0]?.label ?? "",
            label: (item: TooltipItem<"bar">) => {
              const value =
                typeof item.parsed.y === "number" ? item.parsed.y : 0;
              const label = item.dataset.label ?? "Value";
              return `${label}: ${value.toLocaleString()}`;
            },
          },
        },
      },
      scales: {
        x: {
          type: "category" as const,
          stacked,
          title: {
            display: Boolean(xLabel),
            text: xLabel,
            color: "rgba(255,255,255,0.7)",
            font: { size: 12 },
          },
          ticks: {
            color: "rgba(255,255,255,0.7)",
            font: { size: 10 },
            autoSkip: false,
            maxRotation: xTickRotation,
            minRotation: xTickRotation,
          },
          grid: {
            display: false,
          },
        },
        y: {
          beginAtZero: true,
          stacked,
          title: {
            display: Boolean(yLabel),
            text: yLabel,
            color: "rgba(255,255,255,0.7)",
            font: { size: 12 },
          },
          ticks: {
            color: "rgba(255,255,255,0.7)",
            font: { size: 10 },
          },
          grid: {
            color: "rgba(255,255,255,0.15)",
          },
        },
      },
    }),
    [showLegend, stacked, xLabel, xTickRotation, yLabel],
  );

  if (!hasData) {
    return (
      <div className="rounded-xl border border-white/10 bg-white/5 p-4 text-sm text-white/70">
        {emptyMessage}
      </div>
    );
  }

  return (
    <div className="rounded-xl border border-white/10 bg-white/5 p-4">
      <div style={{ height }}>
        <Bar
          data={{ labels, datasets }}
          options={options}
          aria-label="Bar chart"
        />
      </div>
    </div>
  );
};

export const ScatterChart = ({
  points,
  height = DEFAULT_HEIGHT,
  emptyMessage = "No data available.",
  xLabel,
  yLabel,
  pointColors,
}: ScatterChartProps) => {
  const hasPoints = points.length > 0;

  const colors = pointColors?.length ? pointColors : ["rgba(129,140,248,0.7)"];

  const pointBackgroundColor = points.map(
    (_, idx) => colors[idx % colors.length],
  );
  const datasets = useMemo<ChartDataset<"scatter", ScatterPoint[]>[]>(
    () => [
      {
        label: "Teams",
        data: points,
        pointBackgroundColor,
        pointBorderColor: "rgba(255,255,255,0.5)",
        pointBorderWidth: 1,
        pointRadius: 4,
        pointHoverRadius: 6,
        pointHitRadius: 10,
        parsing: false as const,
      },
    ],
    [pointBackgroundColor, points],
  );

  const maxX = hasPoints ? Math.max(...points.map((point) => point.x)) : 1;
  const maxY = hasPoints ? Math.max(...points.map((point) => point.y)) : 1;

  const options = useMemo<ChartOptions<"scatter">>(
    () => ({
      responsive: true,
      maintainAspectRatio: false,
      animation: false,
      interaction: {
        mode: "nearest" as const,
        intersect: true,
      },
      plugins: {
        legend: { display: false },
        tooltip: {
          mode: "nearest",
          intersect: true,
          backgroundColor: "#231437",
          borderColor: "rgba(255,255,255,0.2)",
          borderWidth: 1,
          padding: 10,
          displayColors: false,
          callbacks: {
            title: (items: TooltipItem<"scatter">[]) => {
              const raw = items[0]?.raw as ScatterPoint | undefined;
              return raw?.label ?? "";
            },
            label: (item: TooltipItem<"scatter">) => {
              const raw = item.raw as ScatterPoint;
              return [
                `Team size: ${raw.x.toLocaleString()}`,
                `Solves: ${raw.y.toLocaleString()}`,
              ];
            },
          },
        },
      },
      scales: {
        x: {
          type: "linear" as const,
          beginAtZero: true,
          suggestedMax: maxX,
          title: {
            display: true,
            text: xLabel,
            color: "rgba(255,255,255,0.7)",
            font: { size: 12 },
          },
          ticks: {
            color: "rgba(255,255,255,0.7)",
            font: { size: 10 },
          },
          grid: {
            color: "rgba(255,255,255,0.1)",
          },
        },
        y: {
          beginAtZero: true,
          suggestedMax: maxY,
          title: {
            display: true,
            text: yLabel,
            color: "rgba(255,255,255,0.7)",
            font: { size: 12 },
          },
          ticks: {
            color: "rgba(255,255,255,0.7)",
            font: { size: 10 },
          },
          grid: {
            color: "rgba(255,255,255,0.15)",
          },
        },
      },
    }),
    [maxX, maxY, xLabel, yLabel],
  );

  if (!hasPoints) {
    return (
      <div className="rounded-xl border border-white/10 bg-white/5 p-4 text-sm text-white/70">
        {emptyMessage}
      </div>
    );
  }

  return (
    <div className="rounded-xl border border-white/10 bg-white/5 p-4">
      <div style={{ height }}>
        <Scatter data={{ datasets }} options={options} />
      </div>
    </div>
  );
};

export const BubbleChart = ({
  points,
  height = DEFAULT_HEIGHT,
  emptyMessage = "No data available.",
  xLabel,
  yLabel,
  pointColors,
}: BubbleChartProps) => {
  const hasPoints = points.length > 0;

  const colors = pointColors?.length ? pointColors : ["rgba(129,140,248,0.6)"];

  const pointBackgroundColor = points.map(
    (_, idx) => colors[idx % colors.length],
  );
  const pointHoverBackgroundColor = points.map((point, idx) =>
    toRgba(point.color ?? pointBackgroundColor[idx], 0.95),
  );

  const datasets = useMemo<ChartDataset<"bubble", BubblePoint[]>[]>(
    () => [
      {
        label: "Teams",
        data: points,
        pointBackgroundColor,
        pointBorderColor: "rgba(255,255,255,0.6)",
        pointBorderWidth: 1,
        radius: 0,
        hoverRadius: 0,
        hitRadius: 2,
        pointHoverBackgroundColor,
        pointHoverBorderColor: "rgba(255,255,255,0.95)",
        pointHoverBorderWidth: 3,
      },
    ],
    [pointBackgroundColor, pointHoverBackgroundColor, points],
  );

  const maxX = hasPoints ? Math.max(...points.map((point) => point.x)) : 1;
  const maxY = hasPoints ? Math.max(...points.map((point) => point.y)) : 1;

  const options = useMemo<ChartOptions<"bubble">>(
    () => ({
      responsive: true,
      maintainAspectRatio: false,
      animation: false,
      interaction: {
        mode: "nearest" as const,
        intersect: true,
      },
      plugins: {
        legend: { display: false },
        tooltip: {
          mode: "nearest",
          intersect: true,
          backgroundColor: "#231437",
          borderColor: "rgba(255,255,255,0.2)",
          borderWidth: 1,
          padding: 10,
          displayColors: false,
          callbacks: {
            title: (items: TooltipItem<"bubble">[]) =>
              (items[0]?.raw as BubblePoint | undefined)?.label ?? "",
            label: (item: TooltipItem<"bubble">) => {
              const raw = item.raw as BubblePoint;
              return [
                `Team size: ${raw.teamSize.toLocaleString()}`,
                `Guesses: ${raw.guesses.toLocaleString()}`,
                `Solves: ${raw.solves.toLocaleString()}`,
              ];
            },
          },
        },
      },
      scales: {
        x: {
          type: "linear" as const,
          beginAtZero: true,
          suggestedMax: maxX,
          title: {
            display: true,
            text: xLabel,
            color: "rgba(255,255,255,0.7)",
            font: { size: 12 },
          },
          ticks: {
            color: "rgba(255,255,255,0.7)",
            font: { size: 10 },
          },
          grid: {
            color: "rgba(255,255,255,0.1)",
          },
        },
        y: {
          beginAtZero: true,
          suggestedMax: maxY,
          title: {
            display: true,
            text: yLabel,
            color: "rgba(255,255,255,0.7)",
            font: { size: 12 },
          },
          ticks: {
            color: "rgba(255,255,255,0.7)",
            font: { size: 10 },
          },
          grid: {
            color: "rgba(255,255,255,0.15)",
          },
        },
      },
    }),
    [maxX, maxY, xLabel, yLabel],
  );

  if (!hasPoints) {
    return (
      <div className="rounded-xl border border-white/10 bg-white/5 p-4 text-sm text-white/70">
        {emptyMessage}
      </div>
    );
  }

  return (
    <div className="rounded-xl border border-white/10 bg-white/5 p-4">
      <div style={{ height }}>
        <Bubble data={{ datasets }} options={options} />
      </div>
    </div>
  );
};

export const TimelineChart = ({
  series,
  teamLabels,
  height = DEFAULT_HEIGHT,
  emptyMessage = "No data available.",
  formatAxisTime,
  formatTooltipTime,
  rangeStartMs,
  rangeEndMs,
}: TimelineChartProps) => {
  const allPoints = useMemo(
    () => series.flatMap((entry) => entry.points),
    [series],
  );
  const hasPoints = allPoints.length > 0;

  const minX =
    rangeStartMs ??
    (hasPoints ? Math.min(...allPoints.map((point) => point.x)) : 0);
  const maxX =
    rangeEndMs ??
    (hasPoints ? Math.max(...allPoints.map((point) => point.x)) : 1);

  const datasets = useMemo<ChartDataset<"scatter", TimelinePoint[]>[]>(
    () =>
      series.map((entry) => ({
        label: entry.label,
        data: entry.points,
        pointBackgroundColor: entry.color,
        pointBorderColor: "rgba(255,255,255,0.6)",
        pointBorderWidth: 1,
        pointRadius: 5,
        pointHoverRadius: 7,
        pointHitRadius: 10,
        parsing: false as const,
      })),
    [series],
  );

  const options = useMemo<ChartOptions<"scatter">>(
    () => ({
      responsive: true,
      maintainAspectRatio: false,
      animation: false,
      interaction: {
        mode: "nearest" as const,
        intersect: true,
      },
      plugins: {
        legend: {
          display: true,
          labels: {
            color: "rgba(255,255,255,0.75)",
            usePointStyle: true,
            pointStyle: "circle",
          },
        },
        tooltip: {
          mode: "nearest",
          intersect: true,
          backgroundColor: "#231437",
          borderColor: "rgba(255,255,255,0.2)",
          borderWidth: 1,
          padding: 10,
          displayColors: true,
          callbacks: {
            title: (items: TooltipItem<"scatter">[]) =>
              items[0]?.dataset.label ?? "",
            label: (item: TooltipItem<"scatter">) => {
              const raw = item.raw as TimelinePoint;
              return `${raw.teamLabel} — ${formatTooltipTime(raw.x)}`;
            },
          },
        },
      },
      scales: {
        x: {
          type: "linear" as const,
          min: minX,
          max: maxX,
          ticks: {
            color: "rgba(255,255,255,0.7)",
            font: { size: 10 },
            callback: (value: string | number) => formatAxisTime(Number(value)),
          },
          grid: {
            color: "rgba(255,255,255,0.1)",
          },
        },
        y: {
          type: "category" as const,
          labels: teamLabels,
          ticks: {
            color: "rgba(255,255,255,0.75)",
            font: { size: 11 },
          },
          grid: {
            color: "rgba(255,255,255,0.15)",
          },
        },
      },
    }),
    [formatAxisTime, formatTooltipTime, maxX, minX, teamLabels],
  );

  if (!hasPoints) {
    return (
      <div className="rounded-xl border border-white/10 bg-white/5 p-4 text-sm text-white/70">
        {emptyMessage}
      </div>
    );
  }

  return (
    <div className="rounded-xl border border-white/10 bg-white/5 p-4">
      <div style={{ height }}>
        <Scatter
          data={{ datasets }}
          options={options}
          plugins={[timelineLegendBottomPaddingPlugin]}
        />
      </div>
    </div>
  );
};
