const EVENT_TYPE_LABEL_BY_VALUE = new Map(
  EVENT_TYPE_OPTIONS.map((option) => [option.value, option.label]),
);
const getEventTypeLabel = (
  entry: ActivityEntry,
  puzzleBySlug: Map<string, PuzzleInfo>,
) => {
  const base = EVENT_TYPE_LABEL_BY_VALUE.get(entry.type) ?? entry.type;
  const puzzle = puzzleBySlug.get(entry.slug);
  if (!puzzle?.isTask) return base;
  if (entry.type === "puzzle_guess_submitted") return "Task Guess Submitted";
  if (entry.type === "puzzle_unlockable") return "Task Discovered";
  if (entry.type === "puzzle_unlocked") return "Task Unlocked";
  if (entry.type === "puzzle_solved") return "Task Completed";
  return base;
};

