const parseTimestamp = (value: string): number | null => {
  const trimmed = value.trim();
  if (!trimmed) return null;
  const match =
    /^(\d{4}-\d{2}-\d{2}) (\d{2}:\d{2}:\d{2})(?:\.(\d+))?([+-]\d{2})(?::?(\d{2}))?$/.exec(
      trimmed,
    );
  if (!match) return null;
  const date = match[1];
  const time = match[2];
  const fraction = match[3] ?? "0";
  const tzHour = match[4];
  const tzMinute = match[5] ?? "00";
  const ms = fraction.padEnd(3, "0").slice(0, 3);
  const iso = `${date}T${time}.${ms}${tzHour}:${tzMinute}`;
  const parsed = Date.parse(iso);
  return Number.isFinite(parsed) ? parsed : null;
};

const formatAxisTime = (timestampMs: number) => {
  return new Intl.DateTimeFormat("en-US", {
    month: "short",
    day: "numeric",
    hour: "numeric",
    hour12: true,
    timeZone: "America/New_York",
  }).format(new Date(timestampMs));
};

const formatTimestampWithEt = (timestampMs: number) => {
  const date = new Date(timestampMs);
  const formatter = new Intl.DateTimeFormat("en-US", {
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hour12: false,
    timeZone: "America/New_York",
  });
  const parts = formatter.formatToParts(date);
  const get = (type: string) =>
    parts.find((part) => part.type === type)?.value ?? "";
  const year = get("year");
  const month = get("month");
  const day = get("day");
  const hour = get("hour");
  const minute = get("minute");
  const second = get("second");
  const fraction = `${Math.floor((timestampMs % 1000) / 10)}`.padStart(2, "0");
  return `${year}-${month}-${day} ${hour}:${minute}:${second}.${fraction} ET`;
};

const buildPuzzleInfo = (rows: PuzzleRow[]): PuzzleInfo[] => {
  return rows.map((row) => ({
    slug: row.puzzle_slug,
    title: row.title,
    isTask: toBool(row.is_task),
    roundSlug: row.round_slug,
  }));
};

const buildSolveSeries = (
  teamEvents: TeamEvents,
  teamId: string,
  teamName: string,
  bucketMinutes: number,
  mode: ChartMode,
  rangeStartMs: number,
  rangeEndMs: number,
) => {
  const bucketMs = bucketMinutes * 60 * 1000;
  const minTime = rangeStartMs;
  const maxTime = rangeEndMs;

  const buildCumulative = (timestamps: number[]) => {
    const sorted = timestamps
      .filter((time) => time >= rangeStartMs && time <= rangeEndMs)
      .sort((a, b) => a - b);
    const points: SeriesPoint[] = [];
    let idx = 0;
    for (let t = minTime; t <= maxTime + bucketMs; t += bucketMs) {
      while (idx < sorted.length && sorted[idx] <= t) {
        idx += 1;
      }
      points.push({ x: t, y: idx });
    }
    return points;
  };

  const color = SERIES_COLORS[0];
  const events =
    mode === "solves"
      ? teamEvents.solves
      : mode === "meta"
        ? teamEvents.metaSolves
        : teamEvents.supermetaSolves;

  return [
    {
      id: teamId,
      label: teamName,
      color,
      points: buildCumulative(events),
    },
  ] as Series[];
};

const buildRpSeries = (
  teamEvents: TeamEvents,
  teamId: string,
  teamName: string,
  bucketMinutes: number,
  rangeStartMs: number,
  rangeEndMs: number,
) => {
  const bucketMs = bucketMinutes * 60 * 1000;
  const minTime = rangeStartMs;
  const maxTime = rangeEndMs;

  const buildCumulative = (rpEvents: RpEvent[]) => {
    const sorted = rpEvents
      .filter(
        (event) => event.timeMs >= rangeStartMs && event.timeMs <= rangeEndMs,
      )
      .sort((a, b) => a.timeMs - b.timeMs);
    const points: SeriesPoint[] = [];
    let idx = 0;
    let total = 0;
    for (let t = minTime; t <= maxTime + bucketMs; t += bucketMs) {
      while (idx < sorted.length && sorted[idx].timeMs <= t) {
        total += sorted[idx].delta;
        idx += 1;
      }
      points.push({ x: t, y: total });
    }
    return points;
  };

  return [
    {
      id: teamId,
      label: teamName,
      color: SERIES_COLORS[0],
      points: buildCumulative(teamEvents.rpEvents),
    },
  ] as Series[];
};

const MultiSelectCombobox = ({
  label,
  placeholder,
  searchPlaceholder,
  options,
  selectedValues,
  onChange,
}: {
  label: string;
  placeholder: string;
  searchPlaceholder: string;
  options: MultiSelectOption[];
  selectedValues: string[];
  onChange: (values: string[]) => void;
}) => {
  const selectedSet = useMemo(() => new Set(selectedValues), [selectedValues]);
  const allSelected =
    options.length > 0 && selectedValues.length === options.length;

  const toggleValue = (value: string) => {
    if (selectedSet.has(value)) {
      onChange(selectedValues.filter((entry) => entry !== value));
    } else {
      onChange([...selectedValues, value]);
    }
  };

  const summary =
    selectedValues.length === 0 || allSelected
      ? `${label}: ${placeholder}`
      : `${label}: ${selectedValues.length} selected`;

  return (
    <Popover>
      <PopoverTrigger asChild>
        <button
          type="button"
          className="flex w-full items-center justify-between rounded-md border border-white/30 bg-[#3f255a] px-3 py-1 text-sm text-white shadow-[inset_0_1px_0_rgba(255,255,255,0.2)] hover:bg-[#4a2c6c] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white/40"
          aria-label={`${label} filter`}
        >
          <span className="truncate">{summary}</span>
          <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 opacity-70" />
        </button>
      </PopoverTrigger>
      <PopoverContent className="w-72 p-0 border border-white/20 bg-[#2b183f] text-white shadow-[0_20px_40px_rgba(10,6,24,0.45)] [--accent:rgba(255,255,255,0.15)] [--accent-foreground:rgba(255,255,255,0.95)]">
        <Command className="bg-transparent text-white [&_[cmdk-input-wrapper]]:rounded-t-md [&_[cmdk-input-wrapper]]:border-white/20 [&_[cmdk-input-wrapper]]:bg-[#321a49] [&_[cmdk-item]]:text-white/90 [&_[cmdk-item][data-selected=true]]:!bg-white/15 [&_[cmdk-item][data-selected=true]]:!text-white [&_[cmdk-item]:hover]:!bg-white/10">
          <CommandInput
            placeholder={searchPlaceholder}
            className="text-white placeholder-white/60 focus-visible:outline-none focus-visible:ring-0 focus-visible:ring-offset-0"
          />
          <CommandList>
            <CommandEmpty>No matches found.</CommandEmpty>
            <CommandGroup>
              <CommandItem
                value="__all__"
                onSelect={() => {
                  if (!allSelected) {
                    onChange(options.map((option) => option.value));
                  }
                }}
                className="text-[11px] uppercase tracking-wide text-white/70 data-[selected=true]:!bg-white/20 data-[selected=true]:!text-white hover:!bg-white/10"
              >
                <Check
                  className={cn(
                    "mr-2 h-4 w-4 text-white/70",
                    allSelected ? "opacity-100" : "opacity-0",
                  )}
                />
                <span className="truncate">Select all</span>
              </CommandItem>
              <CommandItem
                value="__none__"
                onSelect={() => {
                  if (selectedValues.length > 0) {
                    onChange([]);
                  }
                }}
                className="text-[11px] uppercase tracking-wide text-white/70 data-[selected=true]:!bg-white/20 data-[selected=true]:!text-white hover:!bg-white/10"
              >
                <Check
                  className={cn(
                    "mr-2 h-4 w-4 text-white/70",
                    selectedValues.length === 0 ? "opacity-100" : "opacity-0",
                  )}
                />
                <span className="truncate">Clear all</span>
              </CommandItem>
              {options.map((option) => {
                const checked = selectedSet.has(option.value);
                return (
                  <CommandItem
                    key={option.value}
                    value={option.label}
                    onSelect={() => {
                      toggleValue(option.value);
                    }}
                    className="text-white/90 data-[selected=true]:!bg-white/15 data-[selected=true]:!text-white hover:!bg-white/10"
                  >
                    <Check
                      className={cn(
                        "mr-2 h-4 w-4",
                        checked ? "opacity-100" : "opacity-0",
                      )}
                    />
                    <span className="truncate">{option.label}</span>
                  </CommandItem>
                );
              })}
            </CommandGroup>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  );
};

const ActivityLogExplorer = ({
  entries,
  puzzleBySlug,
}: {
  entries: ActivityEntry[];
  puzzleBySlug: Map<string, PuzzleInfo>;
}) => {
  const getRoundSlugForEntry = (entry: ActivityEntry) => {
    const puzzle = puzzleBySlug.get(entry.slug);
    if (puzzle?.roundSlug) return puzzle.roundSlug;
    if (ROUND_TITLE_BY_SLUG.has(entry.slug)) return entry.slug;
    return null;
  };

  const [selectedPuzzles, setSelectedPuzzles] = useState<string[]>([]);
  const [selectedRounds, setSelectedRounds] = useState<string[]>([]);
  const [selectedTypes, setSelectedTypes] = useState<string[]>([]);
  const [timestampSort, setTimestampSort] = useState<"desc" | "asc">("asc");
  const [page, setPage] = useState(1);
  const pageSize = 100;
  const [hasInitializedPuzzles, setHasInitializedPuzzles] = useState(false);
  const [hasInitializedRounds, setHasInitializedRounds] = useState(false);
  const [hasInitializedTypes, setHasInitializedTypes] = useState(false);

  const puzzleOptions = useMemo(() => {
    const puzzleSlugs = new Set<string>();
    entries.forEach((entry) => {
      const puzzle = puzzleBySlug.get(entry.slug);
      if (puzzle) {
        puzzleSlugs.add(entry.slug);
      }
    });
    return Array.from(puzzleSlugs)
      .map((slug) => ({
        value: slug,
        label: puzzleBySlug.get(slug)?.title ?? slug,
      }))
      .sort((a, b) => a.label.localeCompare(b.label));
  }, [entries, puzzleBySlug]);

  const roundOptions = useMemo(() => {
    const roundSlugs = new Set<string>();
    entries.forEach((entry) => {
      const puzzle = puzzleBySlug.get(entry.slug);
      if (puzzle) {
        if (puzzle.roundSlug) {
          roundSlugs.add(puzzle.roundSlug);
        }
        return;
      }
      if (ROUND_TITLE_BY_SLUG.has(entry.slug)) {
        roundSlugs.add(entry.slug);
      }
    });
    return Array.from(roundSlugs)
      .map((slug) => ({
        value: slug,
        label: ROUND_TITLE_BY_SLUG.get(slug) ?? slug,
      }))
      .sort((a, b) => a.label.localeCompare(b.label));
  }, [entries, puzzleBySlug]);

  const typeOptions = useMemo(() => {
    const types = new Set(entries.map((entry) => entry.type));
    return EVENT_TYPE_OPTIONS.filter((option) => types.has(option.value));
  }, [entries]);

  useEffect(() => {
    if (!hasInitializedPuzzles && puzzleOptions.length > 0) {
      setSelectedPuzzles(puzzleOptions.map((option) => option.value));
      setHasInitializedPuzzles(true);
    }
  }, [hasInitializedPuzzles, puzzleOptions]);

  useEffect(() => {
    if (!hasInitializedRounds && roundOptions.length > 0) {
      setSelectedRounds(roundOptions.map((option) => option.value));
      setHasInitializedRounds(true);
    }
  }, [hasInitializedRounds, roundOptions]);

  useEffect(() => {
    if (!hasInitializedTypes && typeOptions.length > 0) {
      setSelectedTypes(typeOptions.map((option) => option.value));
      setHasInitializedTypes(true);
    }
  }, [hasInitializedTypes, typeOptions]);

  useEffect(() => {
    setPage(1);
  }, [selectedPuzzles, selectedRounds, selectedTypes, timestampSort]);

  const filteredEntries = useMemo(() => {
    if (hasInitializedTypes && selectedTypes.length === 0) return [];
    if (hasInitializedPuzzles && selectedPuzzles.length === 0) return [];
    if (hasInitializedRounds && selectedRounds.length === 0) return [];

    const puzzleSet = new Set(selectedPuzzles);
    const roundSet = new Set(selectedRounds);
    const typeSet = new Set(selectedTypes);
    return entries.filter((entry) => {
      if (selectedTypes.length > 0 && !typeSet.has(entry.type)) {
        return false;
      }
      if (selectedPuzzles.length > 0) {
        if (!puzzleSet.has(entry.slug)) {
          return false;
        }
      }
      if (selectedRounds.length > 0) {
        const roundSlug = getRoundSlugForEntry(entry);
        if (!roundSlug || !roundSet.has(roundSlug)) {
          return false;
        }
      }
      return true;
    });
  }, [
    entries,
    selectedPuzzles,
    selectedRounds,
    selectedTypes,
    puzzleBySlug,
    hasInitializedTypes,
    hasInitializedPuzzles,
    hasInitializedRounds,
  ]);

  const sortedEntries = useMemo(() => {
    return [...filteredEntries].sort((a, b) => {
      const aTime = a.timeMs ?? 0;
      const bTime = b.timeMs ?? 0;
      return timestampSort === "asc" ? aTime - bTime : bTime - aTime;
    });
  }, [filteredEntries, timestampSort]);

  const totalPages = Math.max(1, Math.ceil(sortedEntries.length / pageSize));
  const safePage = Math.min(page, totalPages);
  const startIndex = (safePage - 1) * pageSize;
  const endIndex = startIndex + pageSize;
  const visibleEntries = sortedEntries.slice(startIndex, endIndex);

  return (
    <div className="space-y-3">
      <div className="grid grid-cols-3 gap-2">
        <MultiSelectCombobox
          label="Event types"
          placeholder="All"
          searchPlaceholder="Search event types"
          options={typeOptions}
          selectedValues={selectedTypes}
          onChange={setSelectedTypes}
        />
        <MultiSelectCombobox
          label="Puzzles/Tasks"
          placeholder="All"
          searchPlaceholder="Search puzzles/tasks"
          options={puzzleOptions}
          selectedValues={selectedPuzzles}
          onChange={setSelectedPuzzles}
        />
        <MultiSelectCombobox
          label="Rounds"
          placeholder="All"
          searchPlaceholder="Search rounds"
          options={roundOptions}
          selectedValues={selectedRounds}
          onChange={setSelectedRounds}
        />
      </div>
      <div className="flex flex-wrap items-center justify-between gap-2 text-xs text-white/70">
        <div>
          Showing{" "}
          {filteredEntries.length === 0
            ? "0"
            : `${(startIndex + 1).toLocaleString()}-${Math.min(
                endIndex,
                filteredEntries.length,
              ).toLocaleString()}`}{" "}
          of {filteredEntries.length.toLocaleString()} entries
        </div>
        <div className="flex items-center gap-2">
          <button
            type="button"
            className="rounded-md border border-white/20 bg-white/5 px-2 py-1 text-xs hover:bg-white/15 disabled:opacity-40"
            onClick={() => {
              setPage((current) => Math.max(1, current - 1));
            }}
            disabled={safePage <= 1}
          >
            Prev
          </button>
          <span>
            Page {safePage} of {totalPages}
          </span>
          <button
            type="button"
            className="rounded-md border border-white/20 bg-white/5 px-2 py-1 text-xs hover:bg-white/15 disabled:opacity-40"
            onClick={() => {
              setPage((current) => Math.min(totalPages, current + 1));
            }}
            disabled={safePage >= totalPages}
          >
            Next
          </button>
        </div>
      </div>
      <div className="overflow-x-auto rounded-xl border border-white/10 bg-white/5">
        <table className="min-w-full text-sm">
          <thead className="bg-white/10 text-xs uppercase tracking-wide text-white/70">
            <tr>
              <th
                className="px-3 py-2 text-left"
                aria-sort={getAriaSort(true, timestampSort)}
              >
                <button
                  type="button"
                  onClick={() => {
                    setTimestampSort((current) =>
                      current === "asc" ? "desc" : "asc",
                    );
                  }}
                  className="inline-flex items-center gap-1 text-left text-xs font-semibold uppercase tracking-wide text-white/80 hover:text-white"
                >
                  Timestamp
                  <span className="text-[10px]">
                    {timestampSort === "asc" ? "↑" : "↓"}
                  </span>
                </button>
              </th>
              <th className="px-3 py-2 text-left">Type</th>
              <th className="px-3 py-2 text-left">Puzzle/Task</th>
              <th className="px-3 py-2 text-left">Round</th>
            </tr>
          </thead>
          <tbody>
            {visibleEntries.map((entry, idx) => {
              const puzzleInfo = puzzleBySlug.get(entry.slug);
              const puzzleTitle = puzzleInfo?.title;
              const roundSlug = getRoundSlugForEntry(entry);
              const roundTitle = roundSlug
                ? (ROUND_TITLE_BY_SLUG.get(roundSlug) ?? roundSlug)
                : "";
              const puzzleStatsHref = puzzleInfo
                ? puzzleInfo.isTask
                  ? `/research_tasks/${entry.slug}/stats`
                  : `/puzzles/${entry.slug}/stats`
                : null;
              const isRoundEvent =
                entry.type === "round_unlockable" ||
                entry.type === "round_unlocked";
              const formattedTimestamp =
                entry.timeMs !== null
                  ? formatTimestampWithEt(entry.timeMs)
                  : entry.timestamp;
              return (
                <tr
                  key={`${entry.timestamp}-${idx}`}
                  className="border-t border-white/10 odd:bg-white/5"
                >
                  <td className="px-3 py-2 text-xs text-white/70">
                    {formattedTimestamp}
                  </td>
                  <td className="px-3 py-2">
                    {getEventTypeLabel(entry, puzzleBySlug)}
                  </td>
                  <td className="px-3 py-2">
                    {isRoundEvent ? (
                      ""
                    ) : puzzleStatsHref ? (
                      <a
                        href={puzzleStatsHref}
                        className="text-white underline decoration-white/30 underline-offset-2 hover:decoration-white/80"
                      >
                        {puzzleTitle ?? entry.slug}
                      </a>
                    ) : (
                      (puzzleTitle ?? entry.slug)
                    )}
                  </td>
                  <td className="px-3 py-2">{roundTitle}</td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
      {filteredEntries.length === 0 && (
        <div className="rounded-lg border border-white/10 bg-white/5 px-4 py-3 text-sm text-white/70">
          No activity entries match these filters.
        </div>
      )}
    </div>
  );
};

const TeamStatsPage = ({ teamId }: { teamId: string }) => {
  const [state, setState] = useState<LoadState>({ status: "loading" });
  const [chartMode, setChartMode] = useState<ChartMode>("solves");
  const chartModeTooltips: Partial<Record<ChartMode, string>> = {
    meta: "Includes 9 capstones, 1 kingdom metameta, 8 artifact metas, 1 artifact metameta, and 6 dimension metas.",
    final:
      "Includes the kingdom metameta, the artifact metameta, and 6 dimension metas.",
  };

  useEffect(() => {
    let cancelled = false;
    const load = async () => {
      try {
        const [teamText, puzzleText, activityText] = await Promise.all([
          loadCsvText(teamInfoCsvUrl),
          loadCsvText(puzzlesTasksCsvUrl),
          loadCsvText(activityLogCsvUrl),
        ]);

        if (cancelled) return;

        const teamInfoRows = parseCsvToObjects<TeamInfoRow>(teamText);
        const puzzleRows = parseCsvToObjects<PuzzleRow>(puzzleText);
        const puzzles = buildPuzzleInfo(puzzleRows);
        const puzzleBySlug = new Map(
          puzzles.map((puzzle) => [puzzle.slug, puzzle]),
        );
        const teamName =
          teamInfoRows.find((row) => row.team_id === teamId)?.team_name ||
          teamInfoRows.find((row) => row.team_id === teamId)?.username ||
          `Team ${teamId}`;

        const nonTaskSlugs = new Set(
          puzzles
            .filter((puzzle) => !puzzle.isTask)
            .map((puzzle) => puzzle.slug),
        );

        const unlockedSlugs = new Set<string>();
        const solvedSlugs = new Set<string>();
        const activityEntries: ActivityEntry[] = [];
        const teamEvents: TeamEvents = {
          solves: [],
          metaSolves: [],
          supermetaSolves: [],
          rpEvents: [],
        };

        let totalRp = 0;
        let header: string[] = [];
        let idxTimestamp = -1;
        let idxTeamId = -1;
        let idxType = -1;
        let idxSlug = -1;
        let idxCurrencyDelta = -1;

        parseCsv(activityText, (row, rowIndex) => {
          if (rowIndex === 0) {
            header = row;
            idxTimestamp = header.indexOf("timestamp");
            idxTeamId = header.indexOf("team_id");
            idxType = header.indexOf("type");
            idxSlug = header.indexOf("slug");
            idxCurrencyDelta = header.indexOf("currency_delta");
            const missing = [
              ["timestamp", idxTimestamp],
              ["team_id", idxTeamId],
              ["type", idxType],
              ["slug", idxSlug],
            ]
              .filter(([, idx]) => idx === -1)
              .map(([name]) => name as string);
            if (missing.length > 0) {
              throw new Error(
                `Missing required columns in activity_log.csv: ${missing.join(", ")}`,
              );
            }
            return;
          }

          const entryTeamId = row[idxTeamId] ?? "";
          if (entryTeamId !== teamId) return;

          const timestamp = row[idxTimestamp] ?? "";
          const type = row[idxType] ?? "";
          const slug = row[idxSlug] ?? "";
          const timeMs = parseTimestamp(timestamp);

          if (!SKIP_ACTIVITY_TYPES.has(type)) {
            activityEntries.push({
              timestamp,
              team_id: entryTeamId,
              type,
              slug,
              timeMs,
            });
          }

          if (type === "puzzle_unlocked" && nonTaskSlugs.has(slug)) {
            unlockedSlugs.add(slug);
          }

          if (type === "puzzle_solved" && nonTaskSlugs.has(slug)) {
            solvedSlugs.add(slug);
            if (timeMs !== null) {
              teamEvents.solves.push(timeMs);
              if (META_SLUGS.has(slug)) {
                teamEvents.metaSolves.push(timeMs);
              }
              if (SUPERMETA_SLUGS.has(slug)) {
                teamEvents.supermetaSolves.push(timeMs);
              }
            }
          }

          if (idxCurrencyDelta !== -1 && timeMs !== null) {
            const deltaValue = row[idxCurrencyDelta] ?? "0";
            const delta = Number(deltaValue) || 0;
            if (delta > 0 && timeMs <= SOLVE_RANGE_END_MS) {
              totalRp += delta;
              teamEvents.rpEvents.push({ timeMs, delta });
            }
          }
        });

        const data: TeamStatsData = {
          teamId,
          teamName,
          totalUnlocked: unlockedSlugs.size,
          totalSolved: solvedSlugs.size,
          totalRp,
          teamEvents,
          activityEntries,
          puzzleBySlug,
        };

        if (!cancelled) {
          setState({ status: "ready", data });
        }
      } catch (error) {
        if (!cancelled) {
          setState({
            status: "error",
            message:
              error instanceof Error
                ? error.message
                : "Failed to load team stats",
          });
        }
      }
    };

    void load();

    return () => {
      cancelled = true;
    };
  }, [teamId]);

  const data = state.status === "ready" ? state.data : null;
  const solveSeries = useMemo(() => {
    if (!data) return [];
    return buildSolveSeries(
      data.teamEvents,
      data.teamId,
      data.teamName,
      15,
      chartMode,
      SOLVE_RANGE_START_MS,
      SOLVE_RANGE_END_MS,
    );
  }, [chartMode, data]);
  const rpSeries = useMemo(() => {
    if (!data) return [];
    return buildRpSeries(
      data.teamEvents,
      data.teamId,
      data.teamName,
      15,
      SOLVE_RANGE_START_MS,
      SOLVE_RANGE_END_MS,
    );
  }, [data]);

  if (state.status === "loading") {
    return (
      <div className={cn(SECTION_CLASS, "text-center text-sm text-white/80")}>
        Loading team stats…
      </div>
    );
  }

  if (state.status === "error") {
    return (
      <div className="rounded-2xl border border-red-300/60 bg-red-500/15 p-6 text-center text-sm text-white/90 shadow-[0_18px_40px_rgba(17,8,35,0.35)]">
        {state.message}
      </div>
    );
  }

  if (!data) {
    return null;
  }

  return (
    <div className="space-y-6">
      <a
        href="/wrapup"
        className="inline-flex items-center text-xs uppercase tracking-wide text-white/70 underline decoration-white/30 underline-offset-2 hover:text-white hover:decoration-white/80"
      >
        ← Back to Wrap-up
      </a>
      <h2 className="text-2xl font-title text-white sm:text-3xl">
        Team Statistics for {data.teamName}
      </h2>

      <section className={SECTION_CLASS}>
        <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">
          <div className={CARD_CLASS}>
            <div className="text-xs uppercase tracking-wide text-white/60">
              Total puzzles unlocked
            </div>
            <div className="text-2xl font-semibold text-white">
              {data.totalUnlocked.toLocaleString()}
            </div>
          </div>
          <div className={CARD_CLASS}>
            <div className="text-xs uppercase tracking-wide text-white/60">
              Total puzzles solved
            </div>
            <div className="text-2xl font-semibold text-white">
              {data.totalSolved.toLocaleString()}
            </div>
          </div>
          <div className={CARD_CLASS}>
            <div className="text-xs uppercase tracking-wide text-white/60">
              Total RP accrued
            </div>
            <div className="text-2xl font-semibold text-white">
              {data.totalRp.toLocaleString()}
            </div>
          </div>
        </div>
      </section>

      <section className={SECTION_CLASS}>
        <div className="space-y-4">
          <div className="flex flex-wrap items-center gap-3 text-sm">
            <span className="text-white/70">Series</span>
            {[
              { id: "solves", label: "Solves" },
              { id: "meta", label: "Meta solves" },
              { id: "final", label: "Final meta solves" },
            ].map((option) => {
              const tooltip = chartModeTooltips[option.id as ChartMode];
              const button = (
                <button
                  type="button"
                  onClick={() => {
                    setChartMode(option.id as ChartMode);
                  }}
                  className={cn(
                    "rounded-full border px-3 py-1 text-sm transition",
                    chartMode === option.id
                      ? "border-white bg-white/30 text-white"
                      : "border-white/30 bg-white/10 text-white/70 hover:bg-white/20",
                  )}
                >
                  {option.label}
                </button>
              );
              if (tooltip) {
                return (
                  <ConditionalTooltip key={option.id} tooltip={tooltip}>
                    {button}
                  </ConditionalTooltip>
                );
              }
              return <React.Fragment key={option.id}>{button}</React.Fragment>;
            })}
            <span className="ml-auto text-xs text-white/60">
              Bucket size: 15 minutes
            </span>
          </div>
          <h3 className="text-lg font-semibold text-white">
            Solves Over Time (as of Noon ET 1/19)
          </h3>
          <LineChart
            series={solveSeries}
            formatAxisTime={formatAxisTime}
            formatTooltipTime={formatTimestampWithEt}
          />
        </div>
      </section>

      <section className={SECTION_CLASS}>
        <div className="space-y-3">
          <h3 className="text-lg font-semibold text-white">
            RP Accrued Over Time (as of Noon ET 1/19)
          </h3>
          <LineChart
            series={rpSeries}
            formatAxisTime={formatAxisTime}
            formatTooltipTime={formatTimestampWithEt}
          />
          <div className="text-xs text-white/60">Bucket size: 15 minutes</div>
        </div>
      </section>

      <section className={SECTION_CLASS}>
        <div className="space-y-3">
          <h3 className="text-lg font-semibold text-white">
            Activity Log Explorer
          </h3>
          <ActivityLogExplorer
            entries={data.activityEntries}
            puzzleBySlug={data.puzzleBySlug}
          />
        </div>
      </section>
    </div>
  );
};

export default TeamStatsPage;
