export type CsvRowHandler = (row: string[], rowIndex: number) => void;

// Minimal CSV parser that handles quoted fields, embedded commas, and newlines.
export const parseCsv = (text: string, onRow: CsvRowHandler) => {
  const row: string[] = [];
  let field = "";
  let inQuotes = false;
  let rowIndex = 0;

  const pushRow = () => {
    // Skip trailing empty row (common when file ends with newline).
    if (row.length === 0 && field === "") {
      return;
    }
    row.push(field);
    onRow([...row], rowIndex);
    row.length = 0;
    field = "";
    rowIndex += 1;
  };

  for (let i = 0; i < text.length; i += 1) {
    const char = text[i];

    if (inQuotes) {
      if (char === '"') {
        const next = text[i + 1];
        if (next === '"') {
          field += '"';
          i += 1;
        } else {
          inQuotes = false;
        }
      } else {
        field += char;
      }
      continue;
    }

    if (char === '"') {
      inQuotes = true;
      continue;
    }

    if (char === ",") {
      row.push(field);
      field = "";
      continue;
    }

    if (char === "\n") {
      pushRow();
      continue;
    }

    if (char === "\r") {
      const next = text[i + 1];
      if (next === "\n") {
        i += 1;
      }
      pushRow();
      continue;
    }

    field += char;
  }

  if (field.length > 0 || row.length > 0) {
    pushRow();
  }
};

export const parseCsvToObjects = <T extends Record<string, string>>(
  text: string,
): T[] => {
  let headers: string[] | null = null;
  const rows: T[] = [];

  parseCsv(text, (row, rowIndex) => {
    if (rowIndex === 0) {
      headers = row;
      return;
    }
    if (!headers) return;
    const obj: Record<string, string> = {};
    headers.forEach((header, idx) => {
      obj[header] = row[idx] ?? "";
    });
    rows.push(obj as T);
  });

  return rows;
};

export const loadCsvText = async (url: string) => {
  const response = await fetch(url);
  if (!response.ok) {
    throw new Error(`Failed to load ${url} (${response.status})`);
  }
  const bytes = await response.arrayBuffer();
  return new TextDecoder("utf-8").decode(bytes);
};
