const getDeathCauseLabel = (
  type: string,
  reason: string,
): DeathCause | null => {
  const normalized = (reason || type).trim().toUpperCase();
  switch (normalized) {
    case "MINE_EXPLOSION_SELF":
      return "Stepping on Mine";
    case "FISH_POISONING":
    case "DEATH_FISH_POISONING":
    case "FISHING_MINIGAME_FAILURE":
      return "Fish Poisoning";
    case "FLAME_TRAP":
    case "DEATH_FLAME_TRAP":
      return "Flame Trap";
    case "SPIKE_TRAP":
    case "DEATH_SPIKE_TRAP":
      return "Spike Trap";
    case "LAVA":
    case "DEATH_LAVA":
      return "Lava";
    case "CAR_RUN_OVER":
    case "DEATH_CAR":
      return "Ran Over by Car";
    case "WISP_ATTACK":
      return "Wisp Attack";
    case "TRAIN_RUN_OVER":
    case "DEATH_TRAIN":
      return "Ran Over by Train";
    default:
      return null;
  }
};

const buildDeathStats = (deathText: string): DeathStats => {
  const teamDeathCounts = new Map<string, number>();
  const causeCounts = MONQUEST_DEATH_CAUSE_ORDER.reduce(
    (acc, cause) => {
      acc[cause] = 0;
      return acc;
    },
    {} as Record<DeathCause, number>,
  );
  let totalDeaths = 0;

  let header: string[] = [];
  let idxTeamId = -1;
  let idxType = -1;
  let idxReason = -1;

  parseCsv(deathText, (row, rowIndex) => {
    if (rowIndex === 0) {
      header = row;
      idxTeamId = header.indexOf("team_id");
      idxType = header.indexOf("type");
      idxReason = header.indexOf("death_reason");
      const missing = [
        ["team_id", idxTeamId],
        ["type", idxType],
        ["death_reason", idxReason],
      ]
        .filter(([, idx]) => idx === -1)
        .map(([name]) => name as string);
      if (missing.length > 0) {
        throw new Error(
          `Missing required columns in gameworld_death_log.csv: ${missing.join(", ")}`,
        );
      }
      return;
    }

    const teamId = row[idxTeamId] ?? "";
    const type = row[idxType] ?? "";
    const reason = row[idxReason] ?? "";
    if (teamId) {
      teamDeathCounts.set(teamId, (teamDeathCounts.get(teamId) ?? 0) + 1);
    }
    totalDeaths += 1;

    const cause = getDeathCauseLabel(type, reason);
    if (cause) {
      causeCounts[cause] = (causeCounts[cause] ?? 0) + 1;
    }
  });

  let leadingCause: DeathStats["leadingCause"] | undefined;
  MONQUEST_DEATH_CAUSE_ORDER.forEach((cause) => {
    const count = causeCounts[cause] ?? 0;
    if (!leadingCause || count > leadingCause.count) {
      leadingCause = { cause, count };
    }
  });
  if (totalDeaths === 0) {
    leadingCause = undefined;
  }

  return {
    totalDeaths,
    teamsWithDeaths: teamDeathCounts.size,
    causeCounts,
    teamDeathCounts,
    leadingCause,
  };
};

const buildMonquestUnlockStats = (
  entries: ActivityEntry[],
): MonquestUnlockStats => {
  const firstUnlockByTeam = new Map<
    string,
    { kitty?: number; bark?: number }
  >();

  entries.forEach((entry) => {
    if (entry.type !== "round_unlocked") return;
    if (
      entry.slug !== MONQUEST_KITTY_ROUND_SLUG &&
      entry.slug !== MONQUEST_BARK_ROUND_SLUG
    ) {
      return;
    }
    const timeMs = entry.timeMs ?? parseTimestamp(entry.timestamp);
    if (!timeMs) return;
    const bucket = firstUnlockByTeam.get(entry.team_id) ?? {};
    if (entry.slug === MONQUEST_KITTY_ROUND_SLUG) {
      if (!bucket.kitty || timeMs < bucket.kitty) {
        bucket.kitty = timeMs;
      }
    } else {
      if (!bucket.bark || timeMs < bucket.bark) {
        bucket.bark = timeMs;
      }
    }
    firstUnlockByTeam.set(entry.team_id, bucket);
  });

  let kittyFirst = 0;
  let barkFirst = 0;
  let tie = 0;
  let totalWithBoth = 0;

  for (const times of firstUnlockByTeam.values()) {
    if (!times.kitty || !times.bark) continue;
    totalWithBoth += 1;
    if (times.kitty < times.bark) {
      kittyFirst += 1;
    } else if (times.bark < times.kitty) {
      barkFirst += 1;
    } else {
      tie += 1;
    }
  }

  return { kittyFirst, barkFirst, tie, totalWithBoth };
};

const buildRoundUnlockStats = (
  entries: ActivityEntry[],
  roundA: string,
  roundB: string,
): RoundUnlockStats => {
  const firstUnlockByTeam = new Map<
    string,
    { roundA?: number; roundB?: number }
  >();

  entries.forEach((entry) => {
    if (entry.type !== "round_unlocked") return;
    if (entry.slug !== roundA && entry.slug !== roundB) return;
    const timeMs = entry.timeMs ?? parseTimestamp(entry.timestamp);
    if (!timeMs) return;
    const bucket = firstUnlockByTeam.get(entry.team_id) ?? {};
    if (entry.slug === roundA) {
      if (!bucket.roundA || timeMs < bucket.roundA) {
        bucket.roundA = timeMs;
      }
    } else {
      if (!bucket.roundB || timeMs < bucket.roundB) {
        bucket.roundB = timeMs;
      }
    }
    firstUnlockByTeam.set(entry.team_id, bucket);
  });

  let roundAFirst = 0;
  let roundBFirst = 0;
  let tie = 0;
  let totalWithBoth = 0;

  for (const times of firstUnlockByTeam.values()) {
    if (!times.roundA || !times.roundB) continue;
    totalWithBoth += 1;
    if (times.roundA < times.roundB) {
      roundAFirst += 1;
    } else if (times.roundB < times.roundA) {
      roundBFirst += 1;
    } else {
      tie += 1;
    }
  }

  return { roundAFirst, roundBFirst, tie, totalWithBoth };
};

const buildLandOfNoNameStats = (
  entries: ActivityEntry[],
): LandOfNoNameStats => {
  const firstLetterCounts = Object.fromEntries(
    ALPHABET_LETTERS.map((letter) => [letter, 0]),
  ) as Record<string, number>;
  const lastLetterCounts = Object.fromEntries(
    ALPHABET_LETTERS.map((letter) => [letter, 0]),
  ) as Record<string, number>;
  const letterOrderCounts = Object.fromEntries(
    ALPHABET_LETTERS.map((letter) => [letter, Array(26).fill(0)]),
  ) as Record<string, number[]>;
  let totalSolves = 0;
  let fastestCompletion: LandOfNoNameStats["fastestCompletion"] | undefined;
  let smallestMetaLetters: LandOfNoNameStats["smallestMetaLetters"] | undefined;

  const solveTimesByTeam = new Map<string, Map<string, number>>();
  const metaSolveTimesByTeam = new Map<string, number>();

  entries.forEach((entry) => {
    const timeMs = entry.timeMs ?? parseTimestamp(entry.timestamp);
    if (!timeMs) return;
    if (entry.type !== "puzzle_solved") return;
    if (entry.slug === LAND_OF_NO_NAME_META_SLUG) {
      const existing = metaSolveTimesByTeam.get(entry.team_id);
      if (!existing || timeMs < existing) {
        metaSolveTimesByTeam.set(entry.team_id, timeMs);
      }
    }
    if (!ALPHABET_LETTER_SLUGS.has(entry.slug)) return;
    const letter = getLetterForSlug(entry.slug);
    if (letter?.length !== 1 || !/[A-Z]/.test(letter)) return;
    totalSolves += 1;
    let teamMap = solveTimesByTeam.get(entry.team_id);
    if (!teamMap) {
      teamMap = new Map();
      solveTimesByTeam.set(entry.team_id, teamMap);
    }
    const existing = teamMap.get(letter);
    if (!existing || timeMs < existing) {
      teamMap.set(letter, timeMs);
    }
  });

  for (const [teamId, teamMap] of solveTimesByTeam.entries()) {
    const solved = Array.from(teamMap.entries())
      .map(([letter, timeMs]) => ({ letter, timeMs }))
      .sort((a, b) => {
        if (a.timeMs !== b.timeMs) return a.timeMs - b.timeMs;
        return a.letter.localeCompare(b.letter);
      });
    if (solved.length === 0) continue;
    const firstLetter = solved[0].letter;
    firstLetterCounts[firstLetter] = (firstLetterCounts[firstLetter] ?? 0) + 1;
    if (solved.length === ALPHABET_LETTERS.length) {
      const lastSolved = solved[ALPHABET_LETTERS.length - 1];
      const lastLetter = lastSolved.letter;
      lastLetterCounts[lastLetter] = (lastLetterCounts[lastLetter] ?? 0) + 1;
      if (
        !fastestCompletion ||
        lastSolved.timeMs < fastestCompletion.completedAtMs
      ) {
        fastestCompletion = {
          teamId,
          completedAtMs: lastSolved.timeMs,
        };
      }
    }
    solved.forEach((entry, index) => {
      if (index >= 26) return;
      const counts = letterOrderCounts[entry.letter];
      if (counts) {
        counts[index] = (counts[index] ?? 0) + 1;
      }
    });
  }

  for (const [teamId, metaSolveTime] of metaSolveTimesByTeam.entries()) {
    const teamMap = solveTimesByTeam.get(teamId);
    const letterCount = teamMap
      ? Array.from(teamMap.values()).filter((time) => time <= metaSolveTime)
          .length
      : 0;
    if (!smallestMetaLetters || letterCount < smallestMetaLetters.letterCount) {
      smallestMetaLetters = { letterCount, teamCount: 1 };
    } else if (letterCount === smallestMetaLetters.letterCount) {
      smallestMetaLetters.teamCount += 1;
    }
  }

  return {
    firstLetterCounts,
    lastLetterCounts,
    letterOrderCounts,
    totalSolves,
    fastestCompletion,
    smallestMetaLetters,
  };
};

const buildHSpaceStats = (entries: ActivityEntry[]): HSpaceStats => {
  const BACKSOLVE_REQUIREMENT = 6;

  const firstBlankCounts = Object.fromEntries(
    HSPACE_BLANK_SLUGS.map((slug) => [slug, 0]),
  );
  const lastBlankCounts = Object.fromEntries(
    HSPACE_BLANK_SLUGS.map((slug) => [slug, 0]),
  );
  const forwardCounts: Record<string, number> = {};
  const forwardBacksolveCounts = Object.fromEntries(
    HSPACE_NORMAL_SLUGS.map((slug) => [slug, { forward: 0, backsolve: 0 }]),
  );

  let teamsWithSolves = 0;
  let leastForward: HSpaceStats["leastForward"] | undefined;

  const solveStatsByTeam = new Map<string, Map<string, number>>();

  entries.forEach((entry) => {
    if (entry.type !== "puzzle_solved") return;
    if (!HSPACE_FEEDER_SLUG_SET.has(entry.slug)) return;
    const timeMs = entry.timeMs ?? parseTimestamp(entry.timestamp);
    if (!timeMs) return;

    let teamMap = solveStatsByTeam.get(entry.team_id);
    if (!teamMap) {
      teamMap = new Map();
      solveStatsByTeam.set(entry.team_id, teamMap);
    }
    const existing = teamMap.get(entry.slug);
    if (!existing || timeMs < existing) {
      teamMap.set(entry.slug, timeMs);
    }
  });

  for (const [teamId, teamMap] of solveStatsByTeam.entries()) {
    const solved = Array.from(teamMap.entries())
      .map(([slug, timeMs]) => ({ slug, timeMs }))
      .sort((a, b) => {
        if (a.timeMs !== b.timeMs) return a.timeMs - b.timeMs;
        return a.slug.localeCompare(b.slug);
      });
    if (solved.length === 0) continue;

    teamsWithSolves += 1;
    let blankCount = 0;
    let normalCount = 0;
    let forwardCount = 0;

    for (const { slug } of solved) {
      if (HSPACE_BLANK_SLUG_SET.has(slug)) {
        blankCount += 1;
        if (blankCount === 1) {
          firstBlankCounts[slug] = (firstBlankCounts[slug] ?? 0) + 1;
        } else if (blankCount === BACKSOLVE_REQUIREMENT) {
          forwardCounts[forwardCount] = (forwardCounts[forwardCount] ?? 0) + 1;
        } else if (blankCount === HSPACE_BLANK_SLUGS.length) {
          lastBlankCounts[slug] = (lastBlankCounts[slug] ?? 0) + 1;
        }
      }
      if (HSPACE_NORMAL_SLUG_SET.has(slug)) {
        normalCount += 1;
        if (blankCount < BACKSOLVE_REQUIREMENT) {
          forwardBacksolveCounts[slug].forward += 1;
          forwardCount += 1;
        } else {
          forwardBacksolveCounts[slug].backsolve += 1;
        }
      }
    }

    const allSolved = blankCount + normalCount >= HSPACE_FEEDER_SLUGS.length;
    if (allSolved) {
      if (!leastForward || forwardCount < leastForward.count) {
        leastForward = {
          teamId,
          count: forwardCount,
        };
      }
    }
  }

  return {
    teamsWithSolves,
    firstBlankCounts,
    lastBlankCounts,
    leastForward,
    forwardCounts,
    forwardBacksolveCounts,
  };
};

const buildCasinoStats = (gachaText: string): CasinoStats => {
  const teamsPulled = new Set<string>();
  const hourlySubmissionsByTeam = new Map<string, number>();
  let totalPulls = 0;
  let totalQuestSolves = 0;
  let totalHourlySubmissions = 0;

  let header: string[] = [];
  let idxTeamId = -1;
  let idxType = -1;
  let idxGuessStatus = -1;

  parseCsv(gachaText, (row, rowIndex) => {
    if (rowIndex === 0) {
      header = row;
      idxTeamId = header.indexOf("team_id");
      idxType = header.indexOf("type");
      idxGuessStatus = header.indexOf("guess_status");
      const missing = [
        ["team_id", idxTeamId],
        ["type", idxType],
        ["guess_status", idxGuessStatus],
      ]
        .filter(([, idx]) => idx === -1)
        .map(([name]) => name as string);
      if (missing.length > 0) {
        throw new Error(
          `Missing required columns in gacha_activity_log.csv: ${missing.join(", ")}`,
        );
      }
      return;
    }

    const teamId = row[idxTeamId] ?? "";
    const type = row[idxType] ?? "";
    if (GACHA_PULL_TYPES.has(type)) {
      totalPulls += 1;
      if (teamId) teamsPulled.add(teamId);
    }
    if (type === "quest_guess") {
      const status = row[idxGuessStatus] ?? "";
      if (status === "correct") {
        totalQuestSolves += 1;
      }
    }
    if (type === "hourly_submission") {
      totalHourlySubmissions += 1;
      if (teamId) {
        hourlySubmissionsByTeam.set(
          teamId,
          (hourlySubmissionsByTeam.get(teamId) ?? 0) + 1,
        );
      }
    }
  });

  return {
    teamsPulled: teamsPulled.size,
    totalPulls,
    totalQuestSolves,
    totalHourlySubmissions,
    hourlySubmissionsByTeam,
  };
};

const buildTerminusStats = (terminusText: string): TerminusStats => {
  const universeCounts = new Map<string, number>();
  const teamTravelCounts = new Map<string, number>();
  const teamsTraveled = new Set<string>();
  let totalTravels = 0;

  let header: string[] = [];
  let idxTeamId = -1;
  let idxUniverse = -1;

  parseCsv(terminusText, (row, rowIndex) => {
    if (rowIndex === 0) {
      header = row;
      idxTeamId = header.indexOf("team_id");
      idxUniverse = header.indexOf("terminus_str");
      const missing = [
        ["team_id", idxTeamId],
        ["terminus_str", idxUniverse],
      ]
        .filter(([, idx]) => idx === -1)
        .map(([name]) => name as string);
      if (missing.length > 0) {
        throw new Error(
          `Missing required columns in terminus_activity_log.csv: ${missing.join(
            ", ",
          )}`,
        );
      }
      return;
    }

    const teamId = row[idxTeamId] ?? "";
    const universe = row[idxUniverse] ?? "";
    if (!teamId || !universe) return;
    totalTravels += 1;
    teamsTraveled.add(teamId);
    universeCounts.set(universe, (universeCounts.get(universe) ?? 0) + 1);
    teamTravelCounts.set(teamId, (teamTravelCounts.get(teamId) ?? 0) + 1);
  });

  let mostCommonUniverse: TerminusStats["mostCommonUniverse"] | undefined;
  for (const [universe, count] of universeCounts.entries()) {
    if (!mostCommonUniverse || count > mostCommonUniverse.count) {
      mostCommonUniverse = { universe, count };
    }
  }

  let topTraveler: TerminusStats["topTraveler"] | undefined;
  for (const [teamId, count] of teamTravelCounts.entries()) {
    if (!topTraveler || count > topTraveler.count) {
      topTraveler = { teamId, count };
    }
  }

  return {
    teamsTraveled: teamsTraveled.size,
    totalTravels,
    universeCounts,
    teamTravelCounts,
    mostCommonUniverse,
    topTraveler,
  };
};

const buildAtlasOfMosaicsStats = (
  atlasText: string,
  levelStats?: LevelStatsData,
): AtlasOfMosaicsStats => {
  const regionCounts = new Map<string, number>();
  const teamExplorationCounts = new Map<string, number>();
  const teamsExplored = new Set<string>();
  let totalExplorations = 0;

  let header: string[] = [];
  let idxTeamId = -1;
  let idxRegion = -1;
  let idxExplorations = -1;

  parseCsv(atlasText, (row, rowIndex) => {
    if (rowIndex === 0) {
      header = row;
      idxTeamId = header.indexOf("team_id");
      idxRegion = header.indexOf("region");
      idxExplorations = header.indexOf("explorations");
      const missing = [
        ["team_id", idxTeamId],
        ["region", idxRegion],
        ["explorations", idxExplorations],
      ]
        .filter(([, idx]) => idx === -1)
        .map(([name]) => name as string);
      if (missing.length > 0) {
        throw new Error(
          `Missing required columns in atlas_stats.csv: ${missing.join(", ")}`,
        );
      }
      return;
    }

    const teamId = row[idxTeamId] ?? "";
    const region = row[idxRegion] ?? "";
    const explorationsStr = row[idxExplorations] ?? "0";
    const explorations = parseInt(explorationsStr, 10) || 0;

    if (!teamId || !region || explorations === 0) return;

    totalExplorations += explorations;
    teamsExplored.add(teamId);

    // Aggregate region counts
    regionCounts.set(region, (regionCounts.get(region) ?? 0) + explorations);

    // Aggregate team exploration counts
    teamExplorationCounts.set(
      teamId,
      (teamExplorationCounts.get(teamId) ?? 0) + explorations,
    );
  });

  let mostCommonRegion: AtlasOfMosaicsStats["mostCommonRegion"] | undefined;
  for (const [region, count] of regionCounts.entries()) {
    if (!mostCommonRegion || count > mostCommonRegion.count) {
      mostCommonRegion = { region, count };
    }
  }

  let topExplorer: AtlasOfMosaicsStats["topExplorer"] | undefined;
  for (const [teamId, count] of teamExplorationCounts.entries()) {
    if (!topExplorer || count > topExplorer.count) {
      topExplorer = { teamId, count };
    }
  }

  return {
    teamsExplored: teamsExplored.size,
    totalExplorations,
    regionCounts,
    teamExplorationCounts,
    mostCommonRegion,
    topExplorer,
    levelStats,
  };
};

const buildHourlyPieCharts = () => {
  const charts = HOURLY_QUESTIONS.map((question, index) => {
    const slug = `hourlies-${index}`;
    const label = `Hourly ${index}`;
    const counts = STATIC_HOURLIES_COUNTS_BY_QUEST[slug] ?? {};
    const entries = Object.entries(counts);
    const totalResponses = entries.reduce((acc, [, value]) => acc + value, 0);
    const sorted = entries.sort((a, b) => b[1] - a[1]);
    const topEntries = sorted.slice(0, 5);
    const otherCount = sorted
      .slice(5)
      .reduce((acc, [, value]) => acc + value, 0);
    const slices: PieSlice[] = topEntries.map(([input, value]) => ({
      label: input,
      value,
    }));
    if (otherCount > 0) {
      slices.push({ label: "Other", value: otherCount });
    }
    return {
      slug,
      label,
      question,
      totalResponses,
      order: index,
      slices,
    };
  });

  return charts;
};

