const CreditsShowcaseEntry = ({ entry }: { entry: CreditsEntry }) => {
  if (entry.type === "subheading") {
    return (
      <div className="text-xs font-semibold uppercase tracking-[0.3em] text-white/60">
        {entry.label}
      </div>
    );
  }
  if (entry.type === "note") {
    return <div className="text-sm text-white/70">{entry.text}</div>;
  }
  if (entry.type === "text") {
    return (
      <div className="space-y-2">
        <div className="text-lg font-semibold text-white">{entry.label}</div>
        <div className="text-base text-white/80">{entry.text}</div>
      </div>
    );
  }
  if (entry.type === "block") {
    return <div className="space-y-4">{entry.content}</div>;
  }
  if (entry.type === "pair") {
    return (
      <div className="flex justify-center">
        <div className="grid w-full max-w-4xl grid-cols-2 gap-x-12 gap-y-6">
          {[entry.left, entry.right].map((item, index) => (
            <div
              key={`${item.label}-${index}`}
              className="space-y-2 text-center"
            >
              <div className="text-base font-semibold text-white/85">
                {item.label}
              </div>
              <CreditsNames names={item.names} />
            </div>
          ))}
        </div>
      </div>
    );
  }
  return (
    <div className="space-y-2">
      <div className="text-lg font-semibold text-white">{entry.label}</div>
      <div className="space-y-1 text-base text-white/80">
        {entry.names.map((name, index) => (
          <div key={`${entry.label}-${name}-${index}`}>{name}</div>
        ))}
      </div>
    </div>
  );
};

const CreditsRow = ({ entry }: { entry: CreditsEntry }) => {
  if (entry.type === "subheading") {
    return (
      <div className="pt-6 text-center text-sm font-semibold uppercase tracking-[0.3em] text-white/60">
        {entry.label}
      </div>
    );
  }
  if (entry.type === "note") {
    return (
      <div className="text-center text-sm text-white/60">{entry.text}</div>
    );
  }
  if (entry.type === "block") {
    return (
      <div className="flex justify-center">
        <div className="w-full max-w-5xl space-y-4">{entry.content}</div>
      </div>
    );
  }
  if (entry.type === "pair") {
    return (
      <div className="flex justify-center">
        <div className="grid w-full max-w-4xl grid-cols-2 gap-x-12 gap-y-6">
          {[entry.left, entry.right].map((item, index) => (
            <div
              key={`${item.label}-${index}`}
              className="space-y-2 text-center"
            >
              <div className="text-base font-semibold text-white/85">
                {item.label}
              </div>
              <CreditsNames names={item.names} />
            </div>
          ))}
        </div>
      </div>
    );
  }
  const shouldUseColumns = entry.type === "role" && entry.names.length >= 12;
  if (shouldUseColumns) {
    return (
      <div className="space-y-3 text-center">
        <div className="text-base font-semibold text-white/85">
          {entry.label}
        </div>
        <div className="flex justify-center">
          <div className="w-full max-w-5xl text-left">
            <CreditsNames names={entry.names} columns={4} />
          </div>
        </div>
      </div>
    );
  }
  return (
    <div className="flex justify-center">
      <div className="grid w-full max-w-4xl grid-cols-2 items-start gap-x-8 gap-y-2">
        <div className="min-w-0 text-right text-base font-semibold text-white/85">
          {entry.label}
        </div>
        <div className="min-w-0 text-left text-base text-white/80">
          {entry.type === "text" ? (
            entry.text
          ) : (
            <CreditsNames names={entry.names} />
          )}
        </div>
      </div>
    </div>
  );
};

