const PIE_COLORS = [
  "#7dd3fc",
  "#f472b6",
  "#34d399",
  "#fbbf24",
  "#a78bfa",
  "#f97316",
  "#60a5fa",
  "#22d3ee",
  "#fb7185",
  "#4ade80",
  "#facc15",
  "#c084fc",
];

const toPieLabel = (value: number) =>
  Number.isInteger(value) ? value.toLocaleString() : value.toFixed(1);

const polarToCartesian = (
  centerX: number,
  centerY: number,
  radius: number,
  angleInDegrees: number,
) => {
  const angleInRadians = ((angleInDegrees - 90) * Math.PI) / 180.0;
  return {
    x: centerX + radius * Math.cos(angleInRadians),
    y: centerY + radius * Math.sin(angleInRadians),
  };
};

const describeArc = (
  x: number,
  y: number,
  radius: number,
  startAngle: number,
  endAngle: number,
) => {
  const start = polarToCartesian(x, y, radius, endAngle);
  const end = polarToCartesian(x, y, radius, startAngle);
  const largeArcFlag = endAngle - startAngle <= 180 ? "0" : "1";
  return [
    "M",
    x,
    y,
    "L",
    start.x,
    start.y,
    "A",
    radius,
    radius,
    0,
    largeArcFlag,
    0,
    end.x,
    end.y,
    "Z",
  ].join(" ");
};

const StatsPieChart = ({
  slices,
  size = 180,
  valueFormatter,
  emptyMessage = "No data yet.",
}: {
  slices: PieSlice[];
  size?: number;
  valueFormatter?: (value: number, percentage: number) => string;
  emptyMessage?: string;
}) => {
  const [hovered, setHovered] = useState<{
    label: string;
    value: number;
    percentage: number;
    color: string;
  } | null>(null);
  const [tooltipPos, setTooltipPos] = useState<{ x: number; y: number } | null>(
    null,
  );
  const total = slices.reduce((acc, s) => acc + Math.max(0, s.value), 0);
  if (total <= 0) {
    return <div className="text-sm text-white/60">{emptyMessage}</div>;
  }
  const data = slices
    .filter((s) => s.value > 0)
    .map((slice, idx) => ({
      ...slice,
      color: PIE_COLORS[idx % PIE_COLORS.length],
    }));
  const radius = size / 2;
  const center = size / 2;
  let currentAngle = 0;
  const EPS = 0.0001;

  const handleMouseMove = (event: React.MouseEvent<SVGSVGElement>) => {
    const rect = event.currentTarget.getBoundingClientRect();
    setTooltipPos({
      x: event.clientX - rect.left,
      y: event.clientY - rect.top,
    });
  };
  const paths = data.map((slice) => {
    const fraction = slice.value / total;
    const angle = fraction * 360;
    const startAngle = currentAngle;
    const endAngle = currentAngle + angle;
    currentAngle = endAngle;
    const color = slice.color;
    const percentage = fraction * 100;
    const isDimmed = hovered && hovered.label !== slice.label;
    const opacity = isDimmed ? 0.35 : 1;
    if (fraction >= 1 - EPS) {
      return (
        <circle
          key={slice.label}
          cx={center}
          cy={center}
          r={radius}
          fill={color}
          opacity={opacity}
          className="cursor-pointer"
          onMouseEnter={() => {
            setHovered({
              label: slice.label,
              value: slice.value,
              percentage,
              color,
            });
          }}
          onMouseLeave={() => {
            setHovered(null);
          }}
        />
      );
    }
    if (fraction <= EPS) {
      return null;
    }
    const d = describeArc(center, center, radius, startAngle, endAngle);
    return (
      <path
        key={slice.label}
        d={d}
        fill={color}
        opacity={opacity}
        className="cursor-pointer"
        onMouseEnter={() => {
          setHovered({
            label: slice.label,
            value: slice.value,
            percentage,
            color,
          });
        }}
        onMouseLeave={() => {
          setHovered(null);
        }}
      />
    );
  });

  return (
    <div className="flex flex-col gap-3 md:flex-row md:items-start">
      <div className="relative shrink-0">
        <svg
          width={size}
          height={size}
          viewBox={`0 0 ${size} ${size}`}
          className="shrink-0"
          onMouseMove={handleMouseMove}
          onMouseLeave={() => {
            setHovered(null);
          }}
        >
          {paths}
        </svg>
        {hovered && tooltipPos && (
          <div
            className="pointer-events-none absolute z-10 rounded-md border border-white/30 bg-[#231437] px-2 py-1 text-xs text-white shadow-lg"
            style={{
              left: Math.min(tooltipPos.x + 12, size - 12),
              top: Math.max(tooltipPos.y - 12, 8),
              transform: "translate(-50%, -100%)",
              whiteSpace: "nowrap",
            }}
          >
            <div className="font-semibold">{hovered.label}</div>
            <div className="text-white/70">
              {toPieLabel(hovered.value)} • {hovered.percentage.toFixed(1)}%
            </div>
          </div>
        )}
      </div>
      <div className="flex flex-col gap-1 text-sm text-white/80">
        {data.map((slice) => {
          const percentage = (slice.value / total) * 100;
          const formatted =
            valueFormatter?.(slice.value, percentage) ??
            `${toPieLabel(slice.value)} (${percentage.toFixed(1)}%)`;
          const isDimmed = hovered && hovered.label !== slice.label;
          return (
            <div
              key={slice.label}
              className={cn(
                "flex items-center gap-2",
                isDimmed && "opacity-40",
              )}
            >
              <span
                className="inline-block h-3 w-3 rounded"
                style={{ backgroundColor: slice.color }}
              />
              <span className="flex-1 truncate">{slice.label}</span>
              <span className="ml-auto text-white/60 tabular-nums">
                {formatted}
              </span>
            </div>
          );
        })}
      </div>
    </div>
  );
};

