const Heatmap = ({
  counts,
  puzzleLinks,
  header,
}: {
  counts: Record<string, number[]>;
  puzzleLinks: Map<string, string>;
  header: { displayed: string; value: string }[];
}) => {
  const maxValue = Math.max(
    0,
    ...Object.values(counts).flatMap((counts) => counts),
  );
  const minAlpha = 0.12;
  const maxAlpha = 0.9;
  const getCellColor = (value: number) => {
    if (value <= 0 || maxValue <= 0) return "rgba(255,255,255,0.05)";
    const alpha =
      minAlpha + (value / maxValue) * Math.max(0, maxAlpha - minAlpha);
    return `rgba(56,189,248,${alpha})`;
  };

  return (
    <div className="overflow-x-auto rounded-xl border border-white/10 bg-white/5 p-4">
      <table className="min-w-[720px] text-xs text-white/80">
        <thead>
          <tr>
            <th className="px-2 py-1 text-left text-white/60">Nth</th>
            {header.map((title) => {
              const href = puzzleLinks.get(title.value);
              return (
                <th
                  key={title.value}
                  className="px-2 py-1 text-center text-white/60"
                >
                  {href ? (
                    <a href={href} className={STATS_LINK_CLASS}>
                      {title.displayed}
                    </a>
                  ) : (
                    title.displayed
                  )}
                </th>
              );
            })}
          </tr>
        </thead>
        <tbody>
          {Array.from({ length: header.length }, (_, idx) => idx + 1).map(
            (rank) => (
              <tr key={`rank-${rank}`} className="border-t border-white/10">
                <th className="px-2 py-1 text-left text-white/60">{rank}</th>
                {header.map((title) => {
                  const count = counts[title.value]?.[rank - 1] ?? 0;
                  return (
                    <td
                      key={`${title.value}-${rank}`}
                      title={`${title.displayed} solved ${rank}th: ${count}`}
                      className="px-2 py-2 text-center"
                      style={{ backgroundColor: getCellColor(count) }}
                    >
                      <span className="tabular-nums text-white/90">
                        {count > 0 ? count : ""}
                      </span>
                    </td>
                  );
                })}
              </tr>
            ),
          )}
        </tbody>
      </table>
      <div className="mt-2 text-xs text-white/50">
        Lighter cells indicate more teams; max count {maxValue.toLocaleString()}
        .
      </div>
    </div>
  );
};

