const buildSeries = (
  teamEvents: Map<string, TeamEvents>,
  selectedTeams: string[],
  teamsById: Map<string, TeamInfo>,
  bucketMinutes: number,
  mode: ChartMode,
  rangeStartMs: number,
  rangeEndMs: number,
) => {
  const events = selectedTeams
    .map((teamId) => ({
      teamId,
      name: teamsById.get(teamId)?.name ?? `Team ${teamId}`,
      events: teamEvents.get(teamId),
    }))
    .filter((entry) => entry.events);

  if (events.length === 0) return [] as Series[];

  const minTime = rangeStartMs;
  const maxTime = rangeEndMs;
  const bucketMs = bucketMinutes * 60 * 1000;

  const buildCumulative = (timestamps: number[]) => {
    const sorted = timestamps
      .filter((time) => time >= rangeStartMs && time <= rangeEndMs)
      .sort((a, b) => a - b);
    const points: SeriesPoint[] = [];
    let idx = 0;
    for (let t = minTime; t <= maxTime + bucketMs; t += bucketMs) {
      while (idx < sorted.length && sorted[idx] <= t) {
        idx += 1;
      }
      points.push({ x: t, y: idx });
    }
    return points;
  };

  const series: Series[] = [];
  let colorIndex = 0;
  for (const entry of events) {
    const baseColor = getTeamColor(entry.teamId, colorIndex, teamsById);
    colorIndex += 1;

    if (mode === "solves") {
      series.push({
        id: entry.teamId,
        label: entry.name,
        color: baseColor,
        points: buildCumulative(entry.events?.solves ?? []),
      });
    }
    if (mode === "meta") {
      series.push({
        id: entry.teamId,
        label: entry.name,
        color: baseColor,
        points: buildCumulative(entry.events?.metaSolves ?? []),
      });
    }
    if (mode === "final") {
      series.push({
        id: entry.teamId,
        label: entry.name,
        color: baseColor,
        points: buildCumulative(entry.events?.supermetaSolves ?? []),
      });
    }
  }

  return series;
};

const buildRpSeries = (
  teamEvents: Map<string, TeamEvents>,
  selectedTeams: string[],
  teamsById: Map<string, TeamInfo>,
  bucketMinutes: number,
  rangeStartMs: number,
  rangeEndMs: number,
) => {
  const events = selectedTeams.map((teamId) => ({
    teamId,
    name: teamsById.get(teamId)?.name ?? `Team ${teamId}`,
    events: teamEvents.get(teamId),
  }));

  if (events.length === 0) return [] as Series[];

  const minTime = rangeStartMs;
  const maxTime = rangeEndMs;
  const bucketMs = bucketMinutes * 60 * 1000;

  const buildCumulative = (rpEvents: RpEvent[]) => {
    const sorted = rpEvents
      .filter(
        (event) => event.timeMs >= rangeStartMs && event.timeMs <= rangeEndMs,
      )
      .sort((a, b) => a.timeMs - b.timeMs);
    const points: SeriesPoint[] = [];
    let idx = 0;
    let total = 0;
    for (let t = minTime; t <= maxTime + bucketMs; t += bucketMs) {
      while (idx < sorted.length && sorted[idx].timeMs <= t) {
        total += sorted[idx].delta;
        idx += 1;
      }
      points.push({ x: t, y: total });
    }
    return points;
  };

  const series: Series[] = [];
  let colorIndex = 0;
  for (const entry of events) {
    const baseColor = getTeamColor(entry.teamId, colorIndex, teamsById);
    colorIndex += 1;
    series.push({
      id: entry.teamId,
      label: entry.name,
      color: baseColor,
      points: buildCumulative(entry.events?.rpEvents ?? []),
    });
  }

  return series;
};

