  const guessSolvePoints = useMemo(() => {
    if (!data) return [] as BubblePoint[];

    const guessCounts = new Map<string, number>();
    data.activityEntries.forEach((entry) => {
      if (entry.type !== "puzzle_guess_submitted") return;
      if (!entry.timeMs || entry.timeMs > FINISHER_CUTOFF_MS) return;
      const puzzle = data.puzzleBySlug.get(entry.slug);
      if (puzzle?.isTask) return;
      if (!entry.team_id) return;
      guessCounts.set(entry.team_id, (guessCounts.get(entry.team_id) ?? 0) + 1);
    });

    const teamSizeById = new Map<string, number>();
    data.teams.forEach((team) => {
      const fallbackSize =
        team.undergrads +
        team.gradStudents +
        team.alums +
        team.facultyStaff +
        team.affiliates +
        team.minors +
        team.otherPeople;
      const size = team.totalPeople > 0 ? team.totalPeople : fallbackSize;
      teamSizeById.set(team.id, size > 0 ? size : 1);
    });

    const rawPoints = data.teams
      .map((team) => {
        const events = data.teamEvents.get(team.id);
        const solves =
          events?.solves.filter((time) => time <= FINISHER_CUTOFF_MS).length ??
          0;
        const guesses = guessCounts.get(team.id) ?? 0;
        if (solves === 0 && guesses === 0) return null;
        return {
          size: teamSizeById.get(team.id) ?? 1,
          guesses,
          solves,
          x: guesses,
          y: solves,
          label: team.name ?? `Team ${team.id}`,
          teamId: team.id,
        };
      })
      .filter(
        (
          point,
        ): point is {
          size: number;
          guesses: number;
          solves: number;
          x: number;
          y: number;
          label: string;
          teamId: string;
        } => point !== null,
      );

    const maxTeamSize = Math.max(1, ...rawPoints.map((point) => point.size));
    const minRadius = 3;
    const maxRadius = 14;

    return rawPoints.map((point, index) => {
      const scale = point.size / maxTeamSize;
      const radius = minRadius + scale * (maxRadius - minRadius);
      return {
        x: point.guesses,
        y: point.solves,
        r: radius,
        label: point.label,
        teamId: point.teamId,
        teamSize: point.size,
        guesses: point.guesses,
        solves: point.solves,
        color: getTeamColor(point.teamId, index, data.teamById),
      };
    });
  }, [data]);

