import React from "react";
import { hydrateRoot } from "react-dom/client";
import PuzzleStatsPage from "../components/stats/PuzzleStatsPage";
import StatsPage from "../components/stats/StatsPage";
import TaskStatsPage from "../components/stats/TaskStatsPage";
import TeamStatsPage from "../components/stats/TeamStatsPage";

const statsElem = document.getElementById("stats-root");
const puzzleStatsElem = document.getElementById("puzzle-stats-root");
const taskStatsElem = document.getElementById("task-stats-root");
const teamStatsElem = document.getElementById("team-stats-root");
if (statsElem) {
  hydrateRoot(statsElem, <StatsPage />);
}

if (puzzleStatsElem) {
  const slug = puzzleStatsElem.getAttribute("data-slug");
  if (slug) {
    hydrateRoot(puzzleStatsElem, <PuzzleStatsPage slug={slug} />);
  } else {
    console.error(
      "Couldn't mount PuzzleStatsPage because data-slug was missing",
    );
  }
}

if (taskStatsElem) {
  const slug = taskStatsElem.getAttribute("data-slug");
  if (slug) {
    hydrateRoot(taskStatsElem, <TaskStatsPage slug={slug} />);
  } else {
    console.error("Couldn't mount TaskStatsPage because data-slug was missing");
  }
}

if (teamStatsElem) {
  const teamId = teamStatsElem.getAttribute("data-team-id");
  if (teamId) {
    hydrateRoot(teamStatsElem, <TeamStatsPage teamId={teamId} />);
  } else {
    console.error(
      "Couldn't mount TeamStatsPage because data-team-id was missing",
    );
  }
}

if (!statsElem && !puzzleStatsElem && !taskStatsElem && !teamStatsElem) {
  console.error("Couldn't mount stats pages because no stats root was found");
}
